1	// Version-support registry: the one place that says what each Minecraft version needs (JDK, pack formats,
2	// capabilities) and whether Cyrus may build for it. Replaces scattered version lists and the old packFormatFor.
3	// Data lives in registry.json so the Next.js app and the plain-Node build service can read the same file.
4	import registryData from "./registry.json";
5	
6	export type Capability = "itemModelDefinitions" | "dialogApi" | "adventure5" | "dataComponentsStable" | "animatedCreatures";
7	export type FormatVersion = { major: number; minor: number };
8	export type VersionRow = {
9	  id: string;
10	  family: "1.21" | "26";
11	  javaRelease: 21 | 25;
12	  status: "supported" | "preview" | "legacy" | "blocked";
13	  buildable: boolean;
14	  paperCoordinate: string | null;
15	  /** Exact stable Paper SERVER build and its jar sha256 (what Test Flight boots); independent of paperCoordinate
16	   *  (the compile API). null/absent = no pin, so the version cannot be test-flown. */
17	  paperBuild?: number | null;
18	  paperServerSha256?: string | null;
19	  resourcePack: FormatVersion | null;
20	  dataPack: FormatVersion | null;
21	  resourcePackClientVerified: boolean;
22	  capabilities: Capability[];
23	};
24	
25	export const VERSIONS: readonly VersionRow[] = registryData.versions as VersionRow[];
26	
27	/** Exact match only: a version the registry does not list is unknown, never guessed. */
28	export function getVersion(id: string): VersionRow | null {
29	  return VERSIONS.find((v) => v.id === id) ?? null;
30	}
31	
32	export const buildableVersions = (): VersionRow[] => VERSIONS.filter((v) => v.buildable);
33	export const hasCapability = (id: string, c: Capability): boolean => !!getVersion(id)?.capabilities.includes(c);
34	
35	export type PackFormatResult =
36	  | { ok: true; format: FormatVersion; clientVerified: boolean }
37	  | { ok: false; error: string };
38	
39	/** Resource-pack format for a version. Fails closed: unknown version, unknown number, or no item-model support. */
40	export function resourcePackFormat(mc: string, opts: { needsItemModels?: boolean } = {}): PackFormatResult {
41	  const v = getVersion(mc);
42	  if (!v) return { ok: false, error: `Minecraft ${mc} is not in the version registry` };
43	  if (!v.resourcePack) return { ok: false, error: `resource pack format for ${mc} is not verified yet` };
44	  if (opts.needsItemModels && !v.capabilities.includes("itemModelDefinitions")) {
45	    return { ok: false, error: `${mc} has no item model definitions (needs 1.21.4+); a legacy custom-model-data emitter is not built yet` };
46	  }
47	  return { ok: true, format: v.resourcePack, clientVerified: v.resourcePackClientVerified };
48	}
