227	// A Minecraft resource pack from validated texture specs: one item model per texture, wired the 1.21.4+ way
228	// (assets/<ns>/items/<name>.json is what `ItemMeta.setItemModel(new NamespacedKey("<ns>", "<name>"))` points at).
229	// Cyrus R1 sound slice: the SAME pack also carries the mod's rendered sounds (one pack per mod, one pack.mcmeta):
230	//   assets/<ns>/sounds/<set>/<event>_<n>.ogg   mono Ogg Vorbis from the render host
231	//   assets/<ns>/sounds.json                    "<set>.<event>": { subtitle, sounds: [{ name "<ns>:<set>/<event>_<n>", weight }] }
232	//   assets/<ns>/lang/en_us.json                the subtitle texts (key subtitles.<ns>.<set>.<event>)
233	// New namespaced keys only (never `replace`, never a minecraft: key); the plugin plays "<ns>:<set>.<event>".
234	import { createHash } from "node:crypto";
235	import { checkSpec, type TextureSpec } from "./dsl";
236	import { encodePng } from "./png";
237	import { render, type Raster } from "./render";
238	import { checkDoc, renderDoc } from "../studios/paint";
239	import { displayFor } from "./display";
240	import { zip } from "./zip";
241	import { emitItemModel, type EmittedItemModel } from "../itemmodel/emit";
242	import { validateItemModels, type ItemModelNeeds } from "../itemmodel/spec";
243	import { getVersion, resourcePackFormat } from "../versions/registry";
244	
245	/** Resource-pack major format for a version, from the version registry. Throws for an unknown/unverified version (never guesses). */
246	export function packFormatFor(mc: string): number {
247	  const r = resourcePackFormat(mc);
248	  if (!r.ok) throw new Error(r.error);
249	  return r.format.major;
250	}
251	
252	export type PackSoundEvent = { set: string; event: string; subtitle: string; files: { index: number; weight: number; data: Buffer }[] };
253	export type BuiltPack = {
254	  packFormat: number; packClientVerified: boolean; zip: Buffer; sha1: string; bytes: number; files: string[]; textures: { name: string; model: string }[]; sounds: { key: string; subtitleKey: string; files: number }[];
255	  /** Cyrus item model states (lib/cyrus/itemmodel): present only when the pack was given item model specs */
256	  itemModels?: { name: string; model: string; states: EmittedItemModel["states"]; needs: ItemModelNeeds }[];
257	  /** Cyrus R4 glyph HUD fonts (lib/cyrus/designer/hud/font.ts): present only when the pack was given font files */
258	  fonts?: string[];
259	};
260	/** Font files of a glyph HUD (lib/cyrus/designer/hud/font.ts hudFont().files): `assets/<ns>/font/*.json` + `assets/<ns>/textures/font/**.png`. */
261	export type PackFontFile = { path: string; data: Buffer };
262	
263	const SET_RE = /^[a-z][a-z0-9_]{1,31}$/;
264	const EVENT_RE = /^[a-z][a-z0-9_]{0,23}$/;
265	
266	/**
267	 * `itemModels` (Cyrus item model states, optional): ItemModelSpec v1 objects. Each spec's idle texture and state
268	 * textures must be textures of this pack; for those textures the flat one-model default below is replaced by the
269	 * spec's definition + one model per state (lib/cyrus/itemmodel/emit.ts). Absent or empty = byte-identical to before.
270	 */
271	export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; sounds?: PackSoundEvent[]; allowPreview?: boolean; itemModels?: unknown[]; fonts?: PackFontFile[]; /** PROPOSED handgun grip fix (./display.ts gripOnFist); off = byte-identical packs */ handgunGripFix?: boolean }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
272	  if (!/^[a-z][a-z0-9_]{1,30}$/.test(opts.namespace)) return { ok: false, error: "namespace must be lowercase letters, digits and underscores" };
273	  const sounds = opts.sounds ?? [];
274	  const fonts = opts.fonts ?? [];
275	  if (opts.textures.length > 24) return { ok: false, error: "a pack holds at most 24 textures" };
276	  if (opts.textures.length === 0 && sounds.length === 0 && fonts.length === 0) return { ok: false, error: "a pack needs at least one texture, sound or HUD font" };
277	  if (fonts.length > 64) return { ok: false, error: "a pack holds at most 64 HUD font files" };
278	  for (const f of fonts) {
279	    const ok = new RegExp(`^assets/${opts.namespace}/(font/[a-z0-9_]{1,32}\\.json|textures/font/[a-z0-9_]{1,32}/[a-z0-9_]{1,65}\\.png)$`).test(f.path);
280	    if (!ok) return { ok: false, error: `HUD font file ${f.path} is outside this mod's font folders` };
281	    if (f.data.length > 64 * 1024) return { ok: false, error: `HUD font file ${f.path} is larger than 64 KB` };
282	    if (f.path.endsWith(".png") && f.data.subarray(1, 4).toString("latin1") !== "PNG") return { ok: false, error: `HUD font file ${f.path} is not a PNG` };
283	  }
284	  if (sounds.length > 24) return { ok: false, error: "a pack holds at most 24 sound events" };
285	  const seen = new Set<string>();
286	  for (const e of sounds) {
287	    if (!SET_RE.test(e.set) || !EVENT_RE.test(e.event)) return { ok: false, error: `bad sound key ${e.set}.${e.event}` };
288	    if (seen.has(`${e.set}.${e.event}`)) return { ok: false, error: `duplicate sound event ${e.set}.${e.event}` };
289	    seen.add(`${e.set}.${e.event}`);
290	    if (!e.files.length || e.files.length > 4) return { ok: false, error: `sound ${e.set}.${e.event} needs 1-4 files` };
291	    if (typeof e.subtitle !== "string" || e.subtitle.trim().length < 3) return { ok: false, error: `sound ${e.set}.${e.event} has no subtitle` };
292	    for (const f of e.files) if (f.data.subarray(0, 4).toString("latin1") !== "OggS") return { ok: false, error: `sound ${e.set}.${e.event} file ${f.index} is not Ogg` };
293	  }
294	  // Each texture is a DSL spec (what builds return) or a Texture Studio doc (spec + sparse paint layer,
295	  // lib/cyrus/studios/paint.ts): the pack ships the COMPOSITE pixels.
296	  const specs: { name: string; raster: () => Raster }[] = [];
297	  for (const [i, t] of opts.textures.entries()) {
298	    const isDoc = !!t && typeof t === "object" && (t as { v?: unknown }).v === 1 && "paint" in (t as object);
299	    let entry: { name: string; raster: () => Raster };
300	    if (isDoc) { const d = checkDoc(t); if (!d.ok) return { ok: false, error: `texture ${i + 1}: ${d.error}` }; entry = { name: d.doc.name, raster: () => renderDoc(d.doc) }; }
301	    else { const c = checkSpec(t); if (!c.ok) return { ok: false, error: `texture ${i + 1}: ${c.error}` }; const spec: TextureSpec = c.spec; entry = { name: spec.name, raster: () => render(spec) }; }
302	    if (specs.some((s) => s.name === entry.name)) return { ok: false, error: `duplicate texture name ${entry.name}` };
303	    specs.push(entry);
304	  }
305	  const ver = getVersion(opts.mcVersion);
306	  if (ver && ver.status === "preview" && !opts.allowPreview) return { ok: false, error: `${opts.mcVersion} is a preview version: its resource packs are not verified in a real client yet` };
307	  const pf = resourcePackFormat(opts.mcVersion, { needsItemModels: opts.textures.length > 0 });
308	  if (!pf.ok) return { ok: false, error: pf.error };
309	  const ims = opts.itemModels ?? [];
310	  const covered = new Set<string>();
311	  if (ims.length) {
312	    const v = validateItemModels(ims, { textures: specs.map((x) => x.name), version: opts.mcVersion });
313	    if (!v.ok) {
314	      const bad = v.errors[0] ?? v.results.flatMap((r, i) => (r.ok ? [] : r.errors.map((e) => ({ ...e, path: `item model ${i + 1}: ${e.path}` }))))[0];
315	      return { ok: false, error: `item model states: ${bad ? `${bad.path}: ${bad.message}` : "invalid"}` };
316	    }
317	    for (const r of v.results) if (r.ok) for (const t of r.needs.textures) covered.add(t);
318	  }
319	  const fmt = pf.format.major;
320	  // item model definitions need format 46+ (1.21.4); a sound-only pack also works on older versions (sounds.json is stable since 1.13)
321	  const minF = opts.textures.length ? 46 : Math.min(46, fmt);
322	  const files: { path: string; data: Buffer }[] = [
323	    { path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: fmt, supported_formats: { min_inclusive: minF, max_inclusive: 999 }, min_format: minF, max_format: 999, description: opts.description.slice(0, 100) } }, null, 2)) },
324	  ];
325	  const ns = opts.namespace;
326	  const rasters = new Map<string, Raster>();
327	  for (const s of specs) {
328	    const raster = s.raster();
329	    rasters.set(s.name, raster);
330	    files.push({ path: `assets/${ns}/textures/item/${s.name}.png`, data: encodePng(raster) });
331	    if (covered.has(s.name)) continue; // its look comes from an item model spec (below)
332	    // explicit display block (lib/cyrus/textures/display.ts): the hand transforms the studio's "In hand" preview shows
333	    files.push({ path: `assets/${ns}/models/item/${s.name}.json`, data: Buffer.from(JSON.stringify({ parent: "minecraft:item/handheld", textures: { layer0: `${ns}:item/${s.name}` }, display: displayFor(s.name, raster, { gripFix: opts.handgunGripFix === true }) }, null, 2)) });
334	    files.push({ path: `assets/${ns}/items/${s.name}.json`, data: Buffer.from(JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${s.name}` } }, null, 2)) });
335	  }
336	  const itemModels: NonNullable<BuiltPack["itemModels"]> = [];
337	  for (const raw of ims) {
338	    const name = (raw as { name: string }).name;
339	    const e = emitItemModel(raw, { namespace: ns, version: opts.mcVersion, textures: specs.map((x) => x.name), idle: rasters.get(name), gripFix: opts.handgunGripFix === true });
340	    if (!e.ok) return { ok: false, error: `item model ${name}: ${e.errors[0]?.message ?? "invalid"}` };
341	    for (const f of e.item.files) files.push({ path: f.path, data: Buffer.from(f.text) });
342	    itemModels.push({ name: e.item.name, model: e.item.model, states: e.item.states, needs: e.item.needs });
343	  }
344	  const packSounds: BuiltPack["sounds"] = [];
345	  if (sounds.length) {
346	    const json: Record<string, unknown> = {};
347	    const lang: Record<string, string> = {};
348	    for (const e of [...sounds].sort((a, b) => (`${a.set}.${a.event}` < `${b.set}.${b.event}` ? -1 : 1))) {
349	      const key = `${e.set}.${e.event}`, sub = `subtitles.${ns}.${key}`;
350	      const list = [...e.files].sort((a, b) => a.index - b.index);
351	      for (const f of list) files.push({ path: `assets/${ns}/sounds/${e.set}/${e.event}_${f.index}.ogg`, data: f.data });
352	      json[key] = { subtitle: sub, sounds: list.map((f) => ({ name: `${ns}:${e.set}/${e.event}_${f.index}`, weight: f.weight })) };
353	      lang[sub] = e.subtitle.trim().slice(0, 60);
354	      packSounds.push({ key: `${ns}:${key}`, subtitleKey: sub, files: list.length });
355	    }
356	    files.push({ path: `assets/${ns}/sounds.json`, data: Buffer.from(JSON.stringify(json, null, 2)) });
357	    files.push({ path: `assets/${ns}/lang/en_us.json`, data: Buffer.from(JSON.stringify(lang, null, 2)) });
358	  }
359	  for (const f of fonts) files.push({ path: f.path, data: f.data });
360	  const z = zip(files);
361	  return { ok: true, pack: { packFormat: fmt, packClientVerified: pf.clientVerified, zip: z, sha1: createHash("sha1").update(z).digest("hex"), bytes: z.length, files: files.map((f) => f.path).sort(), textures: specs.map((s) => ({ name: s.name, model: `${ns}:${s.name}` })), sounds: packSounds, ...(ims.length ? { itemModels } : {}), ...(fonts.length ? { fonts: fonts.map((f) => f.path).sort() } : {}) } };
362	}
363	// Cyrus item model states: the deterministic GENERATOR. ItemModelSpec -> the 1.21.4+ item model definition
364	// (assets/<ns>/items/<name>.json: condition / select / range_dispatch nodes) + one model JSON per state with its full
365	// display block (assets/<ns>/models/item/<name>.json for idle, models/item/<name>/<state>.json for the others). The
366	// textures are the mod's normal TextureSpecs (the pack writes textures/item/<texture>.png as before).
367	// Key order follows the vanilla data generator ("type" first, then alphabetical), indentation 2 spaces like vanilla, so
368	// a definition built from vanilla's own states is BYTE-identical to vanilla's file (test: the vanilla bow).
369	// The same bytes for every version with item model definitions (1.21.4 ... 26.x): the fields Cyrus uses did not change
370	// (26.x only adds an optional `transformation`, 1.21.9+ an `on_shelf` context, neither emitted); 1.21.1 is refused.
371	import type { Raster } from "../textures/render";
372	import type { DisplayOpts } from "../textures/display";
373	import { categoryDisplay, mergeDisplay, type FullDisplay } from "./display";
374	import { DISPLAY_CONTEXTS, itemModelVersionOk, validateItemModel, type DisplayContext, type ItemModelSpec, type ItemModelNeeds, type ImIssue } from "./spec";
375	
376	export const ITEMMODEL_EMITTER_VERSION = "cyrus-itemmodel-1";
377	/** vanilla bow's scale on use_duration: 20 ticks of use = 1.0 */
378	export const USE_DURATION_SCALE = 0.05;
379	
380	type Json = null | boolean | number | string | Json[] | { [k: string]: Json };
381	
382	/** Recursively order keys like vanilla's generator: "type" first, then the rest alphabetically. */
383	export function vanillaOrder(v: Json): Json {
384	  if (Array.isArray(v)) return v.map(vanillaOrder);
385	  if (v && typeof v === "object") {
386	    const keys = Object.keys(v).sort((a, b) => (a === "type" ? -1 : b === "type" ? 1 : a < b ? -1 : a > b ? 1 : 0));
387	    return Object.fromEntries(keys.map((k) => [k, vanillaOrder((v as Record<string, Json>)[k])]));
388	  }
389	  return v;
390	}
