482	/**
483	 * Walk a definition node (ours OR vanilla's) the way the client selects a model, for the properties above. Returns the
484	 * model id, or null for a node it does not understand (special/composite/other properties). Semantics per vanilla:
485	 * condition -> on_true/on_false; select -> the first case whose `when` (a value or a list) matches, else fallback;
486	 * range_dispatch -> the entry with the highest threshold <= value*scale, else fallback.
487	 */
488	export function evalNode(node: unknown, input: ItemRenderInput): string | null {
489	  const n = node as Record<string, unknown>;
490	  if (!n || typeof n !== "object") return null;
491	  switch (n.type) {
492	    case "minecraft:model": return String(n.model);
493	    case "minecraft:condition": {
494	      let v: boolean;
495	      switch (n.property) {
496	        case "minecraft:using_item": v = !!input.using; break;
497	        case "minecraft:selected": v = !!input.selected; break;
498	        case "minecraft:broken": v = !!input.broken; break;
499	        case "minecraft:custom_model_data": v = !!input.flags?.[Number(n.index ?? 0)]; break;
500	        default: return null;
501	      }
502	      return evalNode(v ? n.on_true : n.on_false, input);
503	    }
504	    case "minecraft:select": {
505	      let v: string | null;
506	      switch (n.property) {
507	        case "minecraft:display_context": v = input.context ?? "gui"; break;
508	        case "minecraft:charge_type": v = input.charge ?? "none"; break;
509	        case "minecraft:custom_model_data": v = input.strings?.[Number(n.index ?? 0)] ?? null; break;
510	        default: return null;
511	      }
512	      for (const c of (n.cases as { when: unknown; model: unknown }[]) ?? []) if (v !== null && (Array.isArray(c.when) ? c.when.includes(v) : c.when === v)) return evalNode(c.model, input);
513	      return evalNode(n.fallback, input);
514	    }
515	    case "minecraft:range_dispatch": {
516	      let v: number;
517	      switch (n.property) {
518	        case "minecraft:use_duration": v = input.using ? input.useTicks ?? 0 : 0; break;
519	        case "minecraft:crossbow/pull": v = input.crossbowPull ?? 0; break;
520	        case "minecraft:damage": v = input.damage ?? 0; break;
521	        case "minecraft:custom_model_data": v = input.floats?.[Number(n.index ?? 0)] ?? 0; break;
522	        default: return null;
523	      }
524	      v *= typeof n.scale === "number" ? n.scale : 1;
525	      const es = [...((n.entries as { threshold: number; model: unknown }[]) ?? [])].sort((a, b) => a.threshold - b.threshold);
526	      let pick: unknown = n.fallback;
527	      for (const e of es) if (e.threshold <= v) pick = e.model;
528	      return evalNode(pick, input);
529	    }
530	    default: return null;
531	  }
532	}
