    if (typeof c !== "number" || !Number.isInteger(c) || c <= base || c >= base + CMD_BLOCK) { errors.push(`${at}.cmd must be a whole number from ${base + 1} to ${base + CMD_BLOCK - 1} (this mod's block)`); return; }
    if (seenC.has(c)) { errors.push(`${at}: cmd ${c} is used twice`); return; }
    seenT.add(t); seenC.add(c);
    bindings.push({ texture: t, base: b, cmd: c });
  });
  for (const r of opts.required ?? []) if (!seenT.has(r) && !errors.length) errors.push(`texture ${r} has no binding in ${LEGACY_MANIFEST_PATH} (on 1.21.1 every custom item needs a carrier + number)`);
