export type LegacyEntry = { binding: LegacyBinding; model: string; damage?: { from: number; model: string }[] };
export type LegacyFile = { path: string; text: string };

/**
 * One rewritten vanilla model per carrier used. Overrides are sorted by number, then damage: the client picks the LAST
 * override whose every predicate is <= the stack's value, so this order is what makes each number select its own look.
 */
export function carrierModelFiles(entries: readonly LegacyEntry[]): LegacyFile[] {
  const by = new Map<string, LegacyEntry[]>();
  for (const e of entries) by.set(e.binding.base, [...(by.get(e.binding.base) ?? []), e]);
  const out: LegacyFile[] = [];
  for (const base of [...by.keys()].sort()) {
    const overrides: { model: string; predicate: Record<string, number> }[] = [];
    for (const e of [...by.get(base)!].sort((a, b) => a.binding.cmd - b.binding.cmd)) {
      overrides.push({ model: e.model, predicate: { custom_model_data: e.binding.cmd } });
      for (const d of [...(e.damage ?? [])].sort((a, b) => a.from - b.from)) overrides.push({ model: d.model, predicate: { custom_model_data: e.binding.cmd, damage: d.from } });
