export function evalLegacyModel(modelJson: unknown, stack: { cmd?: number; damage?: number }, fallback = "(vanilla)"): string {
  const ov = ((modelJson as { overrides?: { predicate: Record<string, number>; model: string }[] })?.overrides) ?? [];
  const val: Record<string, number> = { custom_model_data: stack.cmd ?? 0, damage: stack.damage ?? 0 };
  let pick = fallback;
  for (const o of ov) if (Object.entries(o.predicate).every(([k, v]) => (val[k] ?? 0) >= v)) pick = o.model;
  return pick;
}

/** ItemModelSpec state types 1.21.1 can show on a carrier (predicate overrides), and why the others cannot. */
export const LEGACY_STATE_SUPPORT: Readonly<Record<string, string | null>> = Object.freeze({
  damage: null,
  using: "a different look while the item is being used needs item model definitions (1.21.4+); on 1.21.1 only a bow or crossbow has that, and Cyrus does not rewrite those models",
  pull: "bow / crossbow pull stages need item model definitions (1.21.4+) for a custom item",
  charged: "a loaded-crossbow look needs item model definitions (1.21.4+) for a custom item",
  mode: "plugin-set modes need custom_model_data strings (1.21.4+); on 1.21.1 give each look its own texture and number instead",
  flag: "plugin-set flags need custom_model_data flags (1.21.4+); on 1.21.1 give each look its own texture and number instead",
  selected: "a look for the selected hotbar slot needs item model definitions (1.21.4+)",
  context: "a different look per display context (inventory vs hand vs item frame) needs item model definitions (1.21.4+); 1.21.1 only moves/scales the same look",
  broken: "a one-use-from-breaking look needs item model definitions (1.21.4+)",
});

export type AssetLimit = { feature: string; supported: boolean; message: string };

/** What Cyrus can and cannot do with assets on a version, said plainly (the studio + router show these). */
export function versionAssetLimits(mc: string): AssetLimit[] {
  const v = getVersion(mc);
  if (!v) return [{ feature: "version", supported: false, message: `Minecraft ${mc} is not in the version registry` }];
  if (v.capabilities.includes("itemModelDefinitions")) return [];
  if (!isLegacyVersion(v)) return [{ feature: "textures", supported: false, message: `Custom item textures are not available on ${mc}` }];
  return [
    { feature: "textures", supported: true, message: `On ${mc} custom items use the older custom-model-data method: each look rides on a vanilla carrier item (for example a diamond sword or paper) with a number set by the plugin.` },
    { feature: "carrier_conflict", supported: true, message: `The pack rewrites the carrier item's vanilla model, so another resource pack that also changes that same vanilla item (for example diamond_sword) can hide these looks or be hidden by them.` },
    { feature: "carriers", supported: true, message: `Only ${Object.keys(LEGACY_CARRIERS).length} plain vanilla items can carry a look on ${mc} (swords, tools, sticks, gems, ingots, some food); bows, crossbows, shields, tridents and armour cannot.` },
    ...Object.entries(LEGACY_STATE_SUPPORT).filter(([, m]) => m).map(([k, m]) => ({ feature: `state:${k}`, supported: false, message: `Not on ${mc}: ${m}.` })),
    { feature: "state:damage", supported: true, message: `Worn-down looks (damage stages) work on ${mc}.` },
    { feature: "sounds", supported: true, message: `Custom sounds work on ${mc}.` },
  ];
}

