// Cyrus r35 legacy (1.21.1) item looks: registry capability + honest limits, the CMD block, the manifest checker, the
// carrier override emitter (golden bytes) + the client's override selection, damage states, refused states with their
// reasons, and 1.21.4+ packs unchanged.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { getVersion, hasCapability, resourcePackFormat } from "../lib/cyrus/versions/registry";
import { carrierModelFiles, checkLegacyManifest, evalLegacyModel, isLegacyVersion, legacyCmdBase, LEGACY_CARRIERS, versionAssetLimits } from "../lib/cyrus/itemmodel/legacy";
import { emitItemModel } from "../lib/cyrus/itemmodel/emit";
import { buildPack } from "../lib/cyrus/textures/pack";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { HEALTH_POTION } from "../lib/cyrus/textures/sample-items";

const NS = "nx_r1fl1ght";
const BASE = legacyCmdBase(NS);
const ruby = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
const specs = [ruby, HEALTH_POTION].map((s) => { const c = checkSpec(s); if (!c.ok) throw new Error(c.error); return c.spec; });
const manifest = { items: [{ texture: "ruby_sword", base: "diamond_sword", cmd: BASE + 1 }, { texture: "health_potion", base: "minecraft:paper", cmd: BASE + 2 }] };
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");

describe("registry: 1.21.1 legacy capability + limits", () => {
  it("1.21.1 has the legacy path and no item model definitions; 1.21.4+ unchanged", () => {
    assert.equal(hasCapability("1.21.1", "legacyCustomModelData"), true);
    assert.equal(hasCapability("1.21.1", "itemModelDefinitions"), false);
    assert.equal(isLegacyVersion("1.21.1"), true);
    for (const v of ["1.21.4", "1.21.8", "1.21.11", "26.2"]) assert.equal(isLegacyVersion(v), false, v);
    const r = resourcePackFormat("1.21.1", { needsItemModels: true });
    assert.equal(r.ok, false);
    assert.match((r as { error: string }).error, /legacy custom-model-data path/);
    assert.equal(getVersion("1.21.1")!.resourcePack!.major, 34);
  });
  it("versionAssetLimits says what 1.21.1 cannot do; nothing for 1.21.4+", () => {
    const l = versionAssetLimits("1.21.1");
    const no = l.filter((x) => !x.supported).map((x) => x.feature).sort();
    assert.deepEqual(no, ["state:broken", "state:charged", "state:context", "state:flag", "state:mode", "state:pull", "state:selected", "state:using"]);
    assert.ok(l.some((x) => x.feature === "carrier_conflict" && /another resource pack/.test(x.message)));
    assert.deepEqual(versionAssetLimits("1.21.11"), []);
    assert.equal(versionAssetLimits("9.9")[0].supported, false);
  });
});

describe("CMD block + manifest", () => {
  it("block is deterministic and float-exact", () => {
    assert.equal(BASE, legacyCmdBase(NS));
    assert.equal(BASE % 1000, 0);
    assert.ok(BASE >= 1_000_000 && BASE + 999 < 2 ** 24);
    assert.notEqual(legacyCmdBase("nx_aaaaaaaa"), legacyCmdBase("nx_aaaaaaab"));
  });
  it("accepts a good manifest (sorted, minecraft: prefix stripped)", () => {
    const r = checkLegacyManifest(manifest, { namespace: NS, textures: ["ruby_sword", "health_potion"], required: ["ruby_sword", "health_potion"] });
    assert.deepEqual(r, { ok: true, bindings: [{ texture: "ruby_sword", base: "diamond_sword", cmd: BASE + 1 }, { texture: "health_potion", base: "paper", cmd: BASE + 2 }] });
  });
  it("refuses bad bindings with a reason", () => {
    const t = { namespace: NS, textures: ["ruby_sword", "health_potion"] };
    const bad = (items: unknown[], req?: string[]) => { const r = checkLegacyManifest({ items }, { ...t, required: req }); assert.equal(r.ok, false); return (r as { errors: string[] }).errors[0]; };
    assert.match(bad([{ texture: "ruby_sword", base: "diamond_sword", cmd: 5 }]), /this mod's block/);
    assert.match(bad([{ texture: "ruby_sword", base: "bow", cmd: BASE + 1 }]), /legacy carrier/);
    assert.match(bad([{ texture: "nope_tex", base: "paper", cmd: BASE + 1 }]), /not a texture/);
    assert.match(bad([{ texture: "ruby_sword", base: "paper", cmd: BASE + 1 }, { texture: "health_potion", base: "paper", cmd: BASE + 1 }]), /used twice/);
    assert.match(bad([{ texture: "ruby_sword", base: "paper", cmd: BASE + 1, extra: 1 }]), /unknown field/);
    assert.match(bad([{ texture: "ruby_sword", base: "paper", cmd: BASE + 1 }], ["ruby_sword", "health_potion"]), /health_potion has no binding/);
    assert.equal(checkLegacyManifest(null, { ...t }).ok, false);
  });
});

describe("carrier overrides", () => {
  it("golden carrier file + the client's selection", () => {
    const files = carrierModelFiles([
      { binding: { texture: "b", base: "paper", cmd: BASE + 5 }, model: `${NS}:item/b`, damage: [{ from: 0.5, model: `${NS}:item/b/worn` }] },
      { binding: { texture: "a", base: "paper", cmd: BASE + 2 }, model: `${NS}:item/a` },
    ]);
    assert.equal(files.length, 1);
    assert.equal(files[0].path, "assets/minecraft/models/item/paper.json");
    const j = JSON.parse(files[0].text);
    assert.deepEqual(j.overrides.map((o: { predicate: unknown }) => o.predicate), [{ custom_model_data: BASE + 2 }, { custom_model_data: BASE + 5 }, { custom_model_data: BASE + 5, damage: 0.5 }]);
    assert.equal(j.parent, "minecraft:item/generated");
    assert.equal(j.textures.layer0, "minecraft:item/paper");
    assert.equal(evalLegacyModel(j, {}), "(vanilla)");
    assert.equal(evalLegacyModel(j, { cmd: BASE + 2 }), `${NS}:item/a`);
    assert.equal(evalLegacyModel(j, { cmd: BASE + 5 }), `${NS}:item/b`);
    assert.equal(evalLegacyModel(j, { cmd: BASE + 5, damage: 0.7 }), `${NS}:item/b/worn`);
    assert.equal(evalLegacyModel(j, { cmd: BASE + 3 }), `${NS}:item/a`, ">= semantics: a number between two entries shows the lower one (why the plugin must use exact numbers)");
  });
  it("carrier list is plain handheld/generated items only", () => {
    for (const bad of ["bow", "crossbow", "shield", "trident", "clock", "compass", "elytra", "fishing_rod"]) assert.equal(bad in LEGACY_CARRIERS, false, bad);
    assert.equal(LEGACY_CARRIERS.diamond_sword, "handheld");
  });
});

describe("buildPack 1.21.1 (legacy)", () => {
  const built = buildPack({ namespace: NS, description: "Legacy test: custom textures by Cyrus", mcVersion: "1.21.1", textures: specs, legacyModels: manifest });
  it("builds a format-34 pack with carrier overrides and no item model definitions", () => {
    assert.equal(built.ok, true, (built as { error?: string }).error);
    if (!built.ok) return;
    const p = built.pack;
    assert.equal(p.packFormat, 34);
    assert.deepEqual(p.files, [
      "assets/minecraft/models/item/diamond_sword.json", "assets/minecraft/models/item/paper.json",
      `assets/${NS}/models/item/health_potion.json`, `assets/${NS}/models/item/ruby_sword.json`,
      `assets/${NS}/textures/item/health_potion.png`, `assets/${NS}/textures/item/ruby_sword.png`, "pack.mcmeta",
    ]);
    assert.deepEqual(p.legacy, { emitter: "cyrus-legacy-cmd-1", bindings: [{ texture: "ruby_sword", base: "diamond_sword", cmd: BASE + 1 }, { texture: "health_potion", base: "paper", cmd: BASE + 2 }], carriers: ["diamond_sword", "paper"] });
    // deterministic bytes (golden)
    const again = buildPack({ namespace: NS, description: "Legacy test: custom textures by Cyrus", mcVersion: "1.21.1", textures: specs, legacyModels: manifest });
    assert.equal(again.ok && again.pack.sha1, p.sha1);
    assert.equal(p.sha1, "@SHA1@");
  });
  it("needs a binding for every texture", () => {
    const r = buildPack({ namespace: NS, description: "x", mcVersion: "1.21.1", textures: specs });
    assert.equal(r.ok, false);
    assert.match((r as { error: string }).error, /1\.21\.1 legacy item looks: texture ruby_sword has no binding/);
  });
  it("sound-only 1.21.1 packs are unchanged (no legacy block)", () => {
    const ogg = Buffer.concat([Buffer.from("OggS"), Buffer.alloc(40)]);
    const r = buildPack({ namespace: NS, description: "s", mcVersion: "1.21.1", textures: [], sounds: [{ set: "zap", event: "fire", subtitle: "Zap fires", files: [{ index: 1, weight: 1, data: ogg }] }] });
    assert.equal(r.ok, true);
