const LEGACY_TEXTURE_SECTION = TEXTURE_SECTION.replace(''' + repr(bullet).replace("\\'","'") + ''', `- Minecraft ${"1.21.1"} has NO item model API (no setItemModel, no item model definitions). Each custom item gets its look the older way:
    1. pick a vanilla CARRIER item for it from this list only: ${LEGACY_CARRIER_LIST}. Its behaviour stays (a sword carrier still hits like that sword).
    2. give it a number from this mod's custom model data block (in the request) and write the binding in assets/legacy-models.json: {"items": [{"texture": "<texture name>", "base": "<carrier>", "cmd": <number>}, ...]} (one entry per texture, every number different).
    3. in the plugin: ItemStack stack = new ItemStack(Material.<CARRIER>); ItemMeta meta = stack.getItemMeta(); meta.setCustomModelData(<number>); stack.setItemMeta(meta);
  Use exactly the numbers from assets/legacy-models.json. Never call setItemModel, and never send resource packs from the plugin (no setResourcePack/addResourcePack): Nxeon sends the pack. Item looks per state (pulling, aiming, modes) are not available on this version: use a separate texture with its own number instead.`);
if (!LEGACY_TEXTURE_SECTION.includes("setCustomModelData")) throw new Error("LEGACY_TEXTURE_SECTION: the plugin bullet was not replaced");

'''
s=s.replace(anchor, legacy+anchor,1)
s=s.replace('${opts.textures ? TEXTURE_SECTION : ""}','${opts.textures ? (opts.legacy ? LEGACY_TEXTURE_SECTION : TEXTURE_SECTION) : ""}',1)
old='''  const tex = assets.texture ? ` Custom textures are allowed: put them in assets/textures/<name>.json and give each custom item meta.setItemModel(new NamespacedKey("${assets.namespace}", "<name>")).` : "";'''
assert old in s
new='''  const lb = assets.texture && assets.legacy ? require("./itemmodel-spec.js").legacyCmdBase(assets.namespace) : 0;
  const tex = assets.texture && assets.legacy ? ` Custom textures are allowed: put them in assets/textures/<name>.json, bind each in assets/legacy-models.json to a carrier item and a number from this mod's custom model data block ${lb + 1} to ${lb + 999}, and give each custom item meta.setCustomModelData(<its number>) on that carrier Material.`
    : assets.texture ? ` Custom textures are allowed: put them in assets/textures/<name>.json and give each custom item meta.setItemModel(new NamespacedKey("${assets.namespace}", "<name>")).` : "";'''
s=s.replace(old,new,1)
s=s.replace("module.exports = { CONFIG_SECTION,","module.exports = { LEGACY_TEXTURE_SECTION, CONFIG_SECTION,",1)
open(p,'w').write(s)
EOF
