mkdir -p /tank/dev-worktrees/cyrus-r35/services/modbuilder/tools/testflight/fixtures/legacymodel/src/dev/nxeon/tf/legacymodel && cd /tank/dev-worktrees/cyrus-r35/services/modbuilder/tools/testflight/fixtures/legacymodel && cat > plugin.yml <<'EOF'
name: TfLegacyModel
version: 1.0.0
main: dev.nxeon.tf.legacymodel.LegacyModelPlugin
api-version: "@API@"
description: Test Flight fixture for Cyrus 1.21.1 legacy item looks (custom model data on a carrier, like a generated mod)
commands:
  tflegacy:
    description: Builds a carrier item with a custom model data number and prints what it carries
    usage: /tflegacy <carrier> <number>
EOF
cat > src/dev/nxeon/tf/legacymodel/LegacyModelPlugin.java <<'EOF'
package dev.nxeon.tf.legacymodel;

import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Cyrus r35 Test Flight fixture: does exactly what the 1.21.1 build prompt tells a generated mod to do for a custom
 * texture (new ItemStack(Material.CARRIER) + meta.setCustomModelData(number)), then reads the number back, so a flight
 * proves the legacy path works on the real Paper 1.21.1 server (no client involved).
 */
public class LegacyModelPlugin extends JavaPlugin {
    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length != 2) {
            sender.sendMessage("usage: /tflegacy <carrier> <number>");
            return true;
        }
        Material m = Material.matchMaterial(args[0]);
        if (m == null || !m.isItem()) {
            sender.sendMessage("unknown carrier " + args[0]);
            return true;
        }
        ItemStack stack = new ItemStack(m);
        ItemMeta meta = stack.getItemMeta();
        meta.setCustomModelData(Integer.parseInt(args[1]));
        stack.setItemMeta(meta);
        ItemMeta back = stack.getItemMeta();
        String cmd = back != null && back.hasCustomModelData() ? String.valueOf(back.getCustomModelData()) : "none";
        sender.sendMessage("cmd=" + cmd + " material=" + stack.getType().name());
        return true;
    }
}
EOF
