// REAL Test Flight of the Cyrus r35 legacy (1.21.1) item looks on node-2 (not part of the unit suite: boots Paper).
//   devhost run -- npx tsx test/cyrus-legacy-real.ts [--out file.json] --local
// Pipeline: golden texture specs + a legacy manifest -> the portal sync (lib/cyrus/assets/sync.ts: re-validate, render,
// buildPack through the registry = format 34 + carrier overrides, publish to a LocalDiskStore, Pack Loader entry)
// -> packs.json as deliverBuildPack writes it -> ONE flight on Paper 1.21.1 with the Nxeon Pack Loader jar + the
// TfLegacyModel fixture (does what a generated 1.21.1 mod does: setCustomModelData on the carrier, reads it back).
// SERVER SIDE ONLY: no client connects, so the textures showing in a real 1.21.1 client are NOT verified.
// Jars on node-2: <TF root>/inbox/fx/{NxeonPackLoader-0.1.0.jar, TfLegacyModel-1.21.1.jar}
// (TfLegacyModel built by services/modbuilder/tools/testflight/fixtures/build.sh against the 1.21.1 classpath
// <TF root>/classpath/1.21.1.txt = the Paper 1.21.1 server's own libraries + server jar, JDK 21 --release 21).
import { spawn } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe } from "../lib/cyrus/testflight/summary";
import { applyPackChange, LOADER_CONFIG_PATH, serializeLoaderConfig } from "../lib/cyrus/packhost/loader-config";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { HEALTH_POTION } from "../lib/cyrus/textures/sample-items";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { legacyCmdBase } from "../lib/cyrus/itemmodel/legacy";
import { TF_DEFAULT_ROOT } from "../lib/cyrus/testflight/spec";

const FX = `${TF_DEFAULT_ROOT}/inbox/fx`;
const NS = "nx_r35legcy";
const B = legacyCmdBase(NS);
const ruby = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
const specs = [ruby, HEALTH_POTION].map((s) => { const c = checkSpec(s); if (!c.ok) throw new Error(c.error); return c.spec; });
const legacyModels = { items: [{ texture: "ruby_sword", base: "diamond_sword", cmd: B + 1 }, { texture: "health_potion", base: "paper", cmd: B + 2 }] };

export const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {});
    child.stdin.end(opts.input ?? undefined);
  }),
};

async function main() {
  const outIdx = process.argv.indexOf("--out");
  const remote = process.argv.includes("--local") ? localRemote : undefined;
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-r35-legacy-"));
  try {
    const store = new LocalDiskStore(dir, "https://packs.example.invalid");
    const revs: { id: string; modBuildId: string | null }[] = [];
    const deps: AssetSyncDeps = {
      selectStore: () => ({ ok: true, store, maxBytes: 10 * 1024 * 1024 }),
      projectForRootBuild: async () => ({ id: "cp" + "e".repeat(20), namespace: NS, userId: "flight" }),
      createProject: async () => { throw new Error("unexpected"); },
      findRevisionForBuild: async (_p, m) => revs.find((r) => r.modBuildId === m) ?? null,
      headRevisionId: async () => revs.at(-1)?.id ?? null,
      addRevision: async (_p, i) => { const r = { id: `rev${revs.length + 1}`, modBuildId: i.modBuildId ?? null }; revs.push(r); return r; },
      recordAsset: async () => null,
    };
    const a = await syncBuildAssets(
      { id: "mbflight1211", userId: "flight", rootBuildId: "mbflight1211", mcVersion: "1.21.1", pluginName: "TfLegacyModel", jarName: null, jarSha256: null },
      { namespace: NS, promptVersion: null, qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], legacyModels, textures: specs.map((s) => ({ name: s.name, path: `assets/textures/${s.name}.json`, sha256: "", spec: s, quality: null })) },
      deps,
    );
    if (!a || a.status !== "ready" || !a.loader || !a.pack) throw new Error(`sync did not produce a hosted pack: ${JSON.stringify(a)}`);
    const r = applyPackChange(null, { op: "upsert", namespace: NS, role: "main", sha1: a.pack.sha1, prompt: a.loader.prompt, required: a.loader.required }, { urlFor: () => a.loader!.url });
    if (!r.ok) throw new Error(r.error);
    const run = await runTestFlight({
      version: "1.21.1",
      plugins: [{ remotePath: `${FX}/NxeonPackLoader-0.1.0.jar` }, { remotePath: `${FX}/TfLegacyModel-1.21.1.jar` }],
      files: [{ path: LOADER_CONFIG_PATH, content: serializeLoaderConfig(r.config) }],
      rcon: [
        { id: "pack-listed", command: "nxpacks list", expect: ["1 pack(s)", r.id, `sha1=${a.pack.sha1}`], expectNot: ["REJECTED"] },
        { id: "loader-status", command: "nxpacks status", expect: ["packs=1", "config=ok"] },
        { id: "legacy-ruby", command: `tflegacy diamond_sword ${B + 1}`, expect: [`cmd=${B + 1}`, "material=DIAMOND_SWORD"] },
        { id: "legacy-potion", command: `tflegacy paper ${B + 2}`, expect: [`cmd=${B + 2}`, "material=PAPER"] },
        { id: "plugins-listed", command: "plugins", expect: ["NxeonPackLoader", "TfLegacyModel"] },
      ],
    }, { remote });
    const out = {
      name: "legacy-1.21.1", version: run.report.version, status: run.report.status, overall: run.summary.overall, success: run.summary.success,
      bootMs: run.report.bootMs, peakRssKb: run.report.peakRssKb, line: describe(run.summary),
      checks: run.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence })), notes: run.report.notes, engine: run.report.engine,
      pack: { sha1: a.pack.sha1, format: a.pack.format, bytes: a.pack.bytes, legacy: a.legacy, path: "syncBuildAssets (production path)" },
      namespace: NS, cmdBlock: [B + 1, B + 999], client: "none (server-side only)",
    };
    console.log(`1.21.1: ${describe(run.summary)}`);
    if (outIdx > 0) writeFileSync(process.argv[outIdx + 1], JSON.stringify(out, null, 1));
    else console.log(JSON.stringify(out, null, 1));
  } finally { rmSync(dir, { recursive: true, force: true }); }
}
main().catch((e) => { console.error(e); process.exit(1); });

