// Cyrus r35 MULTI-VERSION BUILD: one ModSpec / design builds for several Minecraft versions as a matrix. Pure core +
// an injectable sequential runner (one build and one Test Flight at a time, node-2 rule). Additive and flag-gated
// (CYRUS_BUILD_MATRIX=1); off = nothing here is called and single-version builds are unchanged.
//   planMatrix   per version: buildable? which item-look emitter, JDK, compile API, pack format, honest limits
//   runMatrix    builds each planned version through `deps.build`, then `deps.testFlight`; a failure stays on its row
//   pickForServer  install picks the built version that matches the user's server (lifecycle checkCompat), or says why none
// Every row carries its own status, so "built for 3 of 4, 1.21.1 failed because ..." is what the user sees.
import { createHash } from "node:crypto";
import { getVersion, resourcePackFormat, type VersionRow } from "../versions/registry";
import { isLegacyVersion, versionAssetLimits, type AssetLimit } from "../itemmodel/legacy";
import { checkCompat, compareVersions, type CompatResult } from "../lifecycle/compat";
import { supportFor } from "../lifecycle/support";

export const MATRIX_FLAG = "CYRUS_BUILD_MATRIX";
export const matrixOn = (env: Record<string, string | undefined> = process.env) => env[MATRIX_FLAG] === "1";
/** The versions a matrix offers by default (registry ids; 26.x joins only once the registry marks it buildable). */
export const DEFAULT_MATRIX = ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"] as const;
export const MAX_MATRIX = 6;

export type ItemLookEmitter = "item-model-definitions" | "legacy-custom-model-data" | "none";
export type MatrixPlanRow =
  | { version: string; status: "planned"; javaRelease: number; paperCoordinate: string; paperBuild: number | null; packFormat: number | null; emitter: ItemLookEmitter; limits: AssetLimit[]; testFlight: boolean }
  | { version: string; status: "refused"; reason: string };

export type FlightStatus = "not_run" | "passed" | "failed" | "incomplete" | "busy" | "error";
export type MatrixRow = {
  version: string;
  status: "refused" | "queued" | "building" | "built" | "failed";
  reason?: string;
  plan?: Extract<MatrixPlanRow, { status: "planned" }>;
  buildId?: string;
  jarSha256?: string;
  packSha1?: string | null;
  error?: string;
  testFlight: { status: FlightStatus; runId?: string | null; line?: string };
};
export type MatrixRecord = { schema: 1; matrixId: string; specSha256: string; createdAt: string; rows: MatrixRow[] };

const emitterOf = (v: VersionRow): ItemLookEmitter => (v.capabilities.includes("itemModelDefinitions") ? "item-model-definitions" : isLegacyVersion(v) ? "legacy-custom-model-data" : "none");

/** Per-version plan. Never guesses: unknown, unbuildable or unpinned versions are refused with the reason. */
export function planMatrix(versions: readonly string[], opts: { needsTextures?: boolean } = {}): { ok: true; rows: MatrixPlanRow[] } | { ok: false; error: string } {
  const list = [...new Set(versions)];
  if (!list.length) return { ok: false, error: "pick at least one Minecraft version" };
  if (list.length > MAX_MATRIX) return { ok: false, error: `a matrix builds at most ${MAX_MATRIX} versions` };
  const rows = list.sort(compareVersions).map((id): MatrixPlanRow => {
    const v = getVersion(id);
    if (!v) return { version: id, status: "refused", reason: `Minecraft ${id} is not in the version registry` };
    if (!v.buildable || !v.paperCoordinate) return { version: id, status: "refused", reason: `Minecraft ${id} is ${v.status}: Cyrus cannot build for it yet` };
    const emitter = emitterOf(v);
    if (opts.needsTextures && emitter === "none") return { version: id, status: "refused", reason: `Minecraft ${id} cannot show custom item textures` };
    const pf = resourcePackFormat(id);
    return {
      version: id, status: "planned", javaRelease: v.javaRelease, paperCoordinate: v.paperCoordinate, paperBuild: v.paperBuild ?? null,
      packFormat: pf.ok ? pf.format.major : null, emitter, limits: versionAssetLimits(id), testFlight: !!(v.paperBuild && v.paperServerSha256),
    };
  });
  return { ok: true, rows };
}

export const specSha256 = (spec: unknown) => createHash("sha256").update(JSON.stringify(spec)).digest("hex");

export function newMatrixRecord(spec: unknown, plan: MatrixPlanRow[], now = new Date(), id?: string): MatrixRecord {
  const sha = specSha256(spec);
  return {
    schema: 1, matrixId: id ?? `mx-${sha.slice(0, 12)}-${now.getTime().toString(36)}`, specSha256: sha, createdAt: now.toISOString(),
    rows: plan.map((p) => (p.status === "refused" ? { version: p.version, status: "refused", reason: p.reason, testFlight: { status: "not_run" } } : { version: p.version, status: "queued", plan: p, testFlight: { status: "not_run" } })),
  };
}

export type BuildOutcome = { ok: true; buildId: string; jarSha256: string; packSha1?: string | null } | { ok: false; buildId?: string; error: string };
export type FlightOutcome = { status: FlightStatus; runId?: string | null; line?: string };
export type MatrixDeps = {
  /** Build ONE version from the spec (the per-version emitter + classpath live behind this). Must not throw for a build failure. */
  build: (version: string, plan: Extract<MatrixPlanRow, { status: "planned" }>) => Promise<BuildOutcome>;
  /** Optional Test Flight of a built version (absent = not run, said so). */
  testFlight?: (version: string, built: Extract<BuildOutcome, { ok: true }>) => Promise<FlightOutcome>;
  onUpdate?: (rec: MatrixRecord) => void | Promise<void>;
};

/** Run the matrix strictly one version at a time; every failure (even a thrown one) stays on its own row. */
export async function runMatrix(rec: MatrixRecord, deps: MatrixDeps): Promise<MatrixRecord> {
  const r: MatrixRecord = { ...rec, rows: rec.rows.map((x) => ({ ...x, testFlight: { ...x.testFlight } })) };
  for (const row of r.rows) {
    if (row.status !== "queued" || !row.plan) continue;
    row.status = "building";
    await deps.onUpdate?.(r);
    let out: BuildOutcome;
    try { out = await deps.build(row.version, row.plan); } catch (e) { out = { ok: false, error: `build crashed: ${String((e as Error)?.message ?? e).slice(0, 300)}` }; }
    if (!out.ok) { row.status = "failed"; row.error = out.error; if (out.buildId) row.buildId = out.buildId; await deps.onUpdate?.(r); continue; }
    row.status = "built"; row.buildId = out.buildId; row.jarSha256 = out.jarSha256; row.packSha1 = out.packSha1 ?? null;
    if (deps.testFlight && row.plan.testFlight) {
      try { row.testFlight = await deps.testFlight(row.version, out); } catch (e) { row.testFlight = { status: "error", line: String((e as Error)?.message ?? e).slice(0, 300) }; }
    } else row.testFlight = { status: "not_run", line: row.plan.testFlight ? "no Test Flight requested" : `no pinned Paper server for ${row.version}` };
    await deps.onUpdate?.(r);
  }
  return r;
}

/** One honest sentence per matrix ("Built for 3 of 4 versions; 1.21.1 failed: ..."). */
export function matrixSummary(rec: MatrixRecord): { built: string[]; failed: string[]; refused: string[]; flown: string[]; line: string } {
  const by = (s: MatrixRow["status"]) => rec.rows.filter((x) => x.status === s).map((x) => x.version);
  const built = by("built"), failed = by("failed"), refused = by("refused");
  const flown = rec.rows.filter((x) => x.testFlight.status === "passed").map((x) => x.version);
  const asked = rec.rows.length;
  const parts = [`Built for ${built.length} of ${asked} version${asked === 1 ? "" : "s"}${built.length ? ` (${built.join(", ")})` : ""}`];
  if (flown.length) parts.push(`Test Flight passed on ${flown.join(", ")}`);
  const unflown = built.filter((v) => !flown.includes(v));
  if (unflown.length) parts.push(`not flight-tested or not passed: ${unflown.map((v) => `${v} (${rec.rows.find((x) => x.version === v)!.testFlight.status})`).join(", ")}`);
  for (const v of failed) parts.push(`${v} failed: ${rec.rows.find((x) => x.version === v)!.error}`);
  for (const v of refused) parts.push(`${v} not built: ${rec.rows.find((x) => x.version === v)!.reason}`);
  return { built, failed, refused, flown, line: parts.join("; ") + "." };
}

export type ServerPick =
  | { ok: true; version: string; buildId: string; compat: CompatResult; exact: boolean; flight: FlightStatus; others: { version: string; level: string }[] }
  | { ok: false; reason: string; considered: { version: string; level: string; why: string }[] };

/**
 * Which built version to install on a server. Blocked versions are never picked; among the rest: compat ok before warn,
 * an exact version match first, then a passed Test Flight, then the newest version not newer than the server.
 */
export function pickForServer(rec: MatrixRecord, serverVersion: string | null, game = "minecraft"): ServerPick {
  const support = supportFor(game);
  const built = rec.rows.filter((x) => x.status === "built" && x.buildId);
  if (!support) return { ok: false, reason: `no lifecycle support for ${game}`, considered: [] };
  if (!built.length) return { ok: false, reason: "no version of this mod built successfully", considered: rec.rows.map((x) => ({ version: x.version, level: "none", why: x.error ?? x.reason ?? x.status })) };
  const builtFor = built.map((x) => x.version);
  const scored = built.map((x) => ({ x, c: checkCompat({ support, serverVersion, target: x.version, builtFor }) }));
  const ok = scored.filter((s) => s.c.level !== "block");
  if (!ok.length) return { ok: false, reason: `none of the built versions (${builtFor.join(", ")}) can load on ${serverVersion ?? "this server"}`, considered: scored.map((s) => ({ version: s.x.version, level: s.c.level, why: s.c.reasons[0]?.text ?? "" })) };
  const sv = serverVersion?.trim() ?? null;
  const rank = (s: (typeof ok)[number]) => [
    s.c.level === "ok" ? 0 : 1,
    sv && s.x.version === sv ? 0 : 1,
    s.x.testFlight.status === "passed" ? 0 : 1,
    sv && compareVersions(s.x.version, sv) <= 0 ? 0 : 1,
  ];
  ok.sort((a, b) => {
    const ra = rank(a), rb = rank(b);
    for (let i = 0; i < ra.length; i++) if (ra[i] !== rb[i]) return ra[i] - rb[i];
    return compareVersions(b.x.version, a.x.version);
  });
  const best = ok[0];
  return { ok: true, version: best.x.version, buildId: best.x.buildId!, compat: best.c, exact: !!sv && best.x.version === sv, flight: best.x.testFlight.status, others: scored.filter((s) => s !== best).map((s) => ({ version: s.x.version, level: s.c.level })) };
}

