  if (!ok.length) return { ok: false, reason: `none of the built versions (${builtFor.join(", ")}) can load on ${serverVersion ?? "this server"}`, considered: scored.map((s) => ({ version: s.x.version, level: s.c.level, why: s.c.reasons[0]?.text ?? "" })) };
  const sv = serverVersion?.trim() ?? null;
  const rank = (s: (typeof ok)[number]) => [
    s.c.level === "ok" ? 0 : 1,
