import { legacyCmdBase } from "../lib/cyrus/itemmodel/legacy";
import { matrixSummary, newMatrixRecord, pickForServer, planMatrix, runMatrix, type BuildOutcome } from "../lib/cyrus/matrix";
import { localRemote } from "./cyrus-legacy-real";

const T = TF_DEFAULT_ROOT;
const NS = "nx_r35matrx";
const B = legacyCmdBase(NS);
const ruby = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
const specs = [ruby, HEALTH_POTION].map((s) => { const c = checkSpec(s); if (!c.ok) throw new Error(c.error); return c.spec; });
const DESIGN = { name: "MatrixRuby", namespace: NS, items: [{ texture: "ruby_sword", carrier: "diamond_sword" }, { texture: "health_potion", carrier: "paper" }] };
const legacyModels = { items: DESIGN.items.map((it, i) => ({ texture: it.texture, base: it.carrier, cmd: B + 1 + i })) };

async function main() {
  const remote: Remote = process.argv.includes("--local") ? localRemote : sshRemote();
  const vi = process.argv.indexOf("--versions");
  const versions = vi > 0 ? process.argv[vi + 1].split(",") : ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.2"];
  const outIdx = process.argv.indexOf("--out");
  const plan = planMatrix(versions, { needsTextures: true });
  if (!plan.ok) throw new Error(plan.error);
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-r35-matrix-"));
  const store = new LocalDiskStore(dir, "https://packs.example.invalid");
  const packs = new Map<string, { sha1: string; url: string }>();
  const jars = new Map<string, string>();
  const rec0 = newMatrixRecord(DESIGN, plan.rows);
  try {
    const rec = await runMatrix(rec0, {
      build: async (version, p): Promise<BuildOutcome> => {
        const legacy = p.emitter === "legacy-custom-model-data";
        const built = buildPack({ namespace: NS, description: "MatrixRuby: custom textures by Cyrus", mcVersion: version, textures: specs, ...(legacy ? { legacyModels } : {}) });
        if (!built.ok) return { ok: false, error: `pack: ${built.error}` };
        const pub = await publishPack(store, built.pack.zip, { maxBytes: 10 * 1024 * 1024 });
        if (!pub.ok) return { ok: false, error: `pack publish: ${pub.error}` };
        packs.set(version, { sha1: pub.sha1, url: pub.url });
        const fixture = legacy ? "legacymodel" : "itemmodel";
        const api = version.split(".").slice(0, 2).join(".") === "1.21" ? (legacy ? "1.21" : "1.21.4") : version;
        const jar = `${T}/inbox/fx/TfMatrix-${fixture}-${version}.jar`;
        const cp = `${T}/classpath/${version}.txt`;
        const r = await remote.exec(`test -s ${shq(cp)} || { echo "no classpath for ${version}" >&2; exit 4; }; nice -n 10 bash ${shq(`${T}/fixtures/build.sh`)} ${shq(`${T}/fixtures/${fixture}`)} ${shq(api)} ${shq(`${T}/jdk/${p.javaRelease}`)} ${p.javaRelease} ${shq(cp)} ${shq(jar)}`, { timeoutMs: 300000 });
        if (r.code !== 0) return { ok: false, error: `compile (${fixture} against ${version}): ${(r.stderr || r.stdout).trim().split("\n").slice(-3).join(" | ").slice(0, 400)}` };
        jars.set(version, jar);
        const sha = (r.stdout.trim().split("\n").pop() ?? "").split(/\s+/)[0];
        return { ok: true, buildId: `fixture:${fixture}@${version}`, jarSha256: sha, packSha1: pub.sha1 };
      },
      testFlight: async (version, b) => {
        const pk = packs.get(version)!;
        const lc = applyPackChange(null, { op: "upsert", namespace: NS, role: "main", sha1: pk.sha1, prompt: "MatrixRuby uses custom item textures.", required: false }, { urlFor: () => pk.url });
        if (!lc.ok) throw new Error(lc.error);
        const legacy = b.buildId.includes("legacymodel");
        const look = legacy
          ? [{ id: "look-ruby", command: `tflegacy diamond_sword ${B + 1}`, expect: [`cmd=${B + 1}`, "material=DIAMOND_SWORD"] }]
          : [{ id: "look-ruby", command: `tfitem ${NS} ruby_sword`, expect: [`itemModel=${NS}:ruby_sword`, "material=IRON_SWORD"] }];
        const run = await runTestFlight({
          version,
          plugins: [{ remotePath: `${T}/inbox/fx/NxeonPackLoader-0.1.0.jar` }, { remotePath: jars.get(version)!, sha256: b.jarSha256 }],
          files: [{ path: LOADER_CONFIG_PATH, content: serializeLoaderConfig(lc.config) }],
          rcon: [{ id: "pack-listed", command: "nxpacks list", expect: ["1 pack(s)", `sha1=${pk.sha1}`], expectNot: ["REJECTED"] }, ...look],
        }, { remote });
        console.log(`${version}: ${describe(run.summary)}`);
        const st = run.summary.overall;
        return { status: st === "passed" || st === "failed" || st === "incomplete" || st === "busy" || st === "error" ? st : "error", runId: run.report.runId, line: describe(run.summary) };
      },
    });
    for (const j of jars.values()) await remote.exec(`rm -f -- ${shq(j)}`);
    const picks = ["1.21.1", "1.21.4", "1.21.6", "1.21.11", "26.2", null].map((sv) => ({ server: sv, pick: pickForServer(rec, sv) }));
    const sum = matrixSummary(rec);
    console.log(sum.line);
    const out = { design: DESIGN, designSha256: createHash("sha256").update(JSON.stringify(DESIGN)).digest("hex"), record: rec, summary: sum, picks: picks.map((p) => ({ server: p.server, ...(p.pick.ok ? { version: p.pick.version, level: p.pick.compat.level, exact: p.pick.exact, flight: p.pick.flight } : { none: p.pick.reason }) })) };
    if (outIdx > 0) writeFileSync(process.argv[outIdx + 1], JSON.stringify(out, null, 1));
    else console.log(JSON.stringify(out, null, 1));
  } finally { rmSync(dir, { recursive: true, force: true }); }
}
main().catch((e) => { console.error(e); process.exit(1); });

