// Cyrus r35 multi-version build matrix (pure): per-version plan (emitter, JDK, pack format, refusals), the sequential
// runner (failures and crashes stay on their row, flights per version), the honest summary, and the install pick.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { DEFAULT_MATRIX, matrixOn, matrixSummary, newMatrixRecord, pickForServer, planMatrix, runMatrix, type MatrixRecord } from "../lib/cyrus/matrix";

const planned = (vs: string[]) => { const p = planMatrix(vs, { needsTextures: true }); assert.ok(p.ok); return p.rows; };

describe("planMatrix", () => {
  it("per-version emitter, JDK and pack format; 26.x refused while not buildable", () => {
    const rows = planned([...DEFAULT_MATRIX]);
    const by = Object.fromEntries(rows.map((r) => [r.version, r]));
    assert.deepEqual(rows.map((r) => r.version), ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"]);
    assert.equal(by["1.21.1"].status === "planned" && by["1.21.1"].emitter, "legacy-custom-model-data");
    assert.equal(by["1.21.1"].status === "planned" && by["1.21.1"].packFormat, 34);
    assert.ok(by["1.21.1"].status === "planned" && by["1.21.1"].limits.some((l) => !l.supported));
    assert.equal(by["1.21.11"].status === "planned" && by["1.21.11"].emitter, "item-model-definitions");
    assert.equal(by["1.21.11"].status === "planned" && by["1.21.11"].javaRelease, 21);
    assert.deepEqual(by["1.21.4"].status === "planned" && by["1.21.4"].limits, []);
    for (const v of ["26.1.2", "26.2"]) assert.match(by[v].status === "refused" ? by[v].reason : "", /preview: Cyrus cannot build for it yet/);
  });
  it("refuses unknown versions and bad sizes", () => {
    assert.equal(planMatrix([]).ok, false);
    assert.equal(planMatrix(["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2", "26.3"]).ok, false);
    const r = planned(["1.20.4"]);
    assert.equal(r[0].status, "refused");
  });
  it("flag defaults off", () => { assert.equal(matrixOn({}), false); assert.equal(matrixOn({ CYRUS_BUILD_MATRIX: "1" }), true); });
});

describe("runMatrix + summary", () => {
  it("runs one at a time, keeps failures per version, records flights", async () => {
    const order: string[] = [];
    const rec = newMatrixRecord({ a: 1 }, planned(["1.21.11", "1.21.1", "1.21.4", "26.2"]), new Date(0), "mx-test");
    let active = 0;
    const out = await runMatrix(rec, {
      build: async (v) => {
        active++; assert.equal(active, 1, "one build at a time"); order.push(v);
        await new Promise((r) => setTimeout(r, 2));
        active--;
        if (v === "1.21.4") return { ok: false, buildId: "b4", error: "javac: cannot find symbol setItemModel" };
        if (v === "1.21.1") throw new Error("builder crashed");
        return { ok: true, buildId: `b-${v}`, jarSha256: "f".repeat(64) };
      },
      testFlight: async (v) => ({ status: v === "1.21.11" ? "passed" : "failed", runId: `tf-${v}` }),
    });
    assert.deepEqual(order, ["1.21.1", "1.21.4", "1.21.11"]);
    const st = Object.fromEntries(out.rows.map((r) => [r.version, r.status]));
    assert.deepEqual(st, { "1.21.1": "failed", "1.21.4": "failed", "1.21.11": "built", "26.2": "refused" });
    assert.match(out.rows[0].error!, /build crashed: builder crashed/);
    assert.equal(out.rows.find((r) => r.version === "1.21.11")!.testFlight.status, "passed");
    assert.equal(rec.rows[0].status, "queued", "input record not mutated");
    const s = matrixSummary(out);
    assert.match(s.line, /^Built for 1 of 4 versions \(1\.21\.11\); Test Flight passed on 1\.21\.11; 1\.21\.1 failed: build crashed/);
    assert.match(s.line, /26\.2 not built: Minecraft 26\.2 is preview/);
  });
  it("no flight dep = not_run, said so", async () => {
    const out = await runMatrix(newMatrixRecord({}, planned(["1.21.4"])), { build: async () => ({ ok: true, buildId: "b", jarSha256: "0".repeat(64) }) });
    assert.equal(out.rows[0].testFlight.status, "not_run");
    assert.match(matrixSummary(out).line, /not flight-tested or not passed: 1\.21\.4 \(not_run\)/);
  });
});

describe("pickForServer", () => {
  const rec = (rows: [string, "built" | "failed", ("passed" | "not_run")?][]): MatrixRecord => ({
    schema: 1, matrixId: "m", specSha256: "s", createdAt: "",
    rows: rows.map(([version, status, f]) => ({ version, status, ...(status === "built" ? { buildId: `b-${version}` } : { error: "x" }), testFlight: { status: f ?? "not_run" } })),
  });
  it("exact match wins; otherwise the nearest older one in the same line", () => {
    const r = rec([["1.21.1", "built"], ["1.21.4", "built", "passed"], ["1.21.11", "built"]]);
    const e = pickForServer(r, "1.21.4");
    assert.ok(e.ok); if (e.ok) { assert.equal(e.version, "1.21.4"); assert.equal(e.exact, true); assert.equal(e.compat.level, "ok"); }
    const m = pickForServer(r, "1.21.6");
    assert.ok(m.ok); if (m.ok) { assert.equal(m.version, "1.21.4"); assert.equal(m.exact, false); }
  });
  it("never picks a blocked version; says why when nothing fits", () => {
    const none = pickForServer(rec([["1.21.1", "failed"]]), "1.21.1");
    assert.equal(none.ok, false);
    assert.match(!none.ok ? none.reason : "", /no version of this mod built/);
    const across = pickForServer(rec([["1.21.11", "built"]]), "26.2");
    assert.ok(!across.ok || across.version === "1.21.11");
  });
});

