  if (s.resourcePack && (!/^https?:\/\/[^\s]{4,400}$/.test(s.resourcePack.url || "") || !SHA1.test(s.resourcePack.sha1 || ""))) p.push("resourcePack needs an http(s) url and a sha1");
  if (!s.owner || !MCNAME_RE.test(s.owner.name || "")) p.push("owner.name must be a Minecraft name");
  if (s.expose === true && s.onlineMode !== true) p.push("an exposed session must be online-mode (no offline-mode server on a public port)");
  if (s.expose === true && !process.env.TRYIT_PUBLIC_HOST) p.push("exposing needs TRYIT_PUBLIC_HOST on the build host (owner setup: firewall range + DNS)");
  for (const f of s.files || []) if (!L.SERVER_FILE_RE.test(f.path || "") || typeof f.content !== "string" || f.content.length > 65536) p.push(`bad file ${f && f.path}`);
  if ((s.files || []).length > 8) p.push("at most 8 files");
  for (const c of s.rcon || []) if (typeof c.command !== "string" || /^(stop|restart|op|deop|reload|whitelist|ban|pardon|save-|execute)\b/i.test(c.command.trim()) || c.command.length > 200) p.push(`rcon command not allowed: ${c.command}`);
  if ((s.rcon || []).length > 6) p.push("at most 6 rcon checks");
  return p;
}

function props(s, port, rconPort, rconPassword) {
  const base = L.serverProperties({ port, rconPort, rconPassword, resourcePack: s.resourcePack ? { ...s.resourcePack, required: s.resourcePack.required !== false } : null, world: {} });
  const over = {
    "server-ip": s.expose ? "0.0.0.0" : "127.0.0.1", "online-mode": s.onlineMode ? "true" : "false", "enforce-secure-profile": s.onlineMode ? "true" : "false",
    "max-players": String(Math.min(CAPS.players, Math.max(1, s.maxPlayers || 1))), "enable-status": "true", "white-list": "true", "enforce-whitelist": "true",
    "motd": "Nxeon Try It (temporary)", "pvp": "false", "allow-flight": "true", "gamemode": "creative",
  };
  const lines = base.split("\n").map((l) => { const k = l.split("=")[0]; return k in over ? `${k}=${over[k]}` : l; });
  for (const [k, v] of Object.entries(over)) if (!lines.some((l) => l.startsWith(`${k}=`))) lines.splice(lines.length - 1, 0, `${k}=${v}`);
  return lines.join("\n").replace("#Nxeon Test Flight (generated)", "#Nxeon Try It (generated)");
}

function rcon(port, password, timeoutMs = 10000) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let buf = Buffer.alloc(0); const waiters = []; let next = 100;
    const t = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
    sock.on("data", (d) => { buf = Buffer.concat([buf, d]); const r = L.rconParse(buf); buf = r.rest; for (const p of r.packets) for (const w of [...waiters]) w(p); });
    sock.on("error", (e) => { clearTimeout(t); reject(e); });
    const req = (type, body) => new Promise((res, rej) => {
      const id = next++; let text = "", q = null;
      const w = (p) => { if (p.id === -1 && type === 3) { rej(new Error("rcon auth refused")); return; } if (p.id !== id) return; text += p.body; clearTimeout(q); q = setTimeout(() => { waiters.splice(waiters.indexOf(w), 1); res(text); }, type === 3 ? 0 : 300); };
      setTimeout(() => { if (waiters.includes(w)) { waiters.splice(waiters.indexOf(w), 1); text ? res(text) : rej(new Error("rcon timeout")); } }, timeoutMs);
      waiters.push(w); sock.write(L.rconPacket(id, type, body));
    });
    sock.on("connect", async () => { clearTimeout(t); try { await req(3, password); resolve({ cmd: (c) => req(2, c).then(L.stripColors), close: () => sock.destroy() }); } catch (e) { sock.destroy(); reject(e); } });
  });
}

async function fetchSha1(url, timeoutMs = 15000) {
  const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), timeoutMs);
  try {
    const r = await fetch(url, { signal: ctl.signal, redirect: "error" });
    if (!r.ok) return { ok: false, error: `HTTP ${r.status}` };
    const b = Buffer.from(await r.arrayBuffer());
    if (b.length > 100 * 1024 * 1024) return { ok: false, error: "pack larger than 100 MB" };
    return { ok: true, sha1: crypto.createHash("sha1").update(b).digest("hex"), bytes: b.length };
  } catch (e) { return { ok: false, error: String(e.message || e).slice(0, 200) }; } finally { clearTimeout(t); }
}

function teardown(id, why) {
  const st = readState(id);
  const ev = [];
  if (isActive(id)) {
    sh("systemctl", ["stop", `${unitOf(id)}.service`], { timeout: 90000 });
    ev.push(`unit ${unitOf(id)} stopped (${why})`);
  }
  sh("systemctl", ["stop", `${unitOf(id)}-reap.timer`, `${unitOf(id)}-reap.service`]);
  const alive = isActive(id);
  const ports = st ? [st.port, st.rconPort].filter((p) => listening().has(p)) : [];
  if (!alive) fs.rmSync(path.join(DIR, id), { recursive: true, force: true });
  ev.push(`unit active: ${alive}; ports still listening: ${ports.length ? ports.join(",") : "none"}; dir removed: ${!fs.existsSync(path.join(DIR, id))}`);
  return { ok: !alive && !ports.length, evidence: ev };
}

async function create(specPath) {
  const s = JSON.parse(fs.readFileSync(specPath, "utf8"));
  const bad = validate(s);
  if (bad.length) fail("invalid", bad.join("; "));
  const ttl = Math.min(CAPS.ttlSec, Math.max(120, s.ttlSec || 1200));
  const xmx = Math.min(CAPS.xmxMb, Math.max(512, s.xmxMb || 1024));
  const prep = withLock(() => {
    const live = sessions().filter((x) => isActive(x.id));
    if (live.some((x) => x.userId === s.userId)) fail("user_active", "you already have a Try-It server running; stop it first");
    if (live.length >= MAX_ACTIVE) fail("busy", "all Try-It servers are in use; try again in a few minutes");
    const ledgerP = path.join(DIR, "ledger.json");
    let ledger = {}; try { ledger = JSON.parse(fs.readFileSync(ledgerP, "utf8")); } catch { ledger = {}; }
    const key = `${day()}:${s.userId}`;
    if ((ledger[key] || 0) >= DAILY) fail("daily_limit", `at most ${DAILY} Try-It servers per day`);
    for (const k of Object.keys(ledger)) if (!k.startsWith(day())) delete ledger[k];
    ledger[key] = (ledger[key] || 0) + 1;
    fs.writeFileSync(ledgerP, JSON.stringify(ledger), { mode: 0o600 });
    const used = listening();
    let port = 0, rconPort = 0;
    for (let i = 0; i < 200 && (!port || !rconPort); i++) {
      const p = PORTS.min + crypto.randomInt(PORTS.max - PORTS.min + 1);
      if (used.has(p) || p === port) continue;
      if (!port) port = p; else rconPort = p;
    }
    if (!port || !rconPort) fail("busy", "no free Try-It port");
    const dir = path.join(DIR, s.id), srv = path.join(dir, "server");
    if (fs.existsSync(dir)) fail("invalid", "session id already exists");
    fs.mkdirSync(path.join(srv, "plugins"), { recursive: true, mode: 0o700 });
    const state = { id: s.id, userId: s.userId, version: s.version, port, rconPort, createdAt: new Date().toISOString(), expiresAt: new Date(Date.now() + ttl * 1000).toISOString(), expose: !!s.expose, owner: s.owner.name, resourcePack: s.resourcePack || null, unit: unitOf(s.id) };
    fs.writeFileSync(path.join(dir, "state.json"), JSON.stringify(state), { mode: 0o600 });
    return state;
  });
  const dir = path.join(DIR, s.id), srv = path.join(dir, "server");
  const ev = [];
  const rconPassword = crypto.randomBytes(18).toString("base64url");
  fs.writeFileSync(path.join(dir, "rcon.secret"), rconPassword, { mode: 0o600 });
  try {
    const paperDir = path.join(ROOT, "paper", s.paper.sha256), jar = path.join(paperDir, "paper.jar");
    if (!fs.existsSync(jar) || sha256File(jar) !== s.paper.sha256) throw new Error("pinned Paper jar is not prepared on this host (run one Test Flight on the version first)");
    const java = path.join(ROOT, "jdk", String(s.javaRelease), "bin/java");
    if (!fs.existsSync(java)) throw new Error(`JDK ${s.javaRelease} is not prepared on this host`);
    for (const pl of s.plugins) {
      if (sha256File(pl.path) !== pl.sha256) throw new Error(`${path.basename(pl.path)}: sha256 mismatch`);
      fs.copyFileSync(pl.path, path.join(srv, "plugins", path.basename(pl.path)));
    }
    for (const f of s.files || []) { fs.mkdirSync(path.dirname(path.join(srv, f.path)), { recursive: true }); fs.writeFileSync(path.join(srv, f.path), f.content); }
    fs.writeFileSync(path.join(srv, "eula.txt"), "eula=true\n");
    fs.writeFileSync(path.join(srv, "server.properties"), props(s, prep.port, prep.rconPort, rconPassword));
    fs.writeFileSync(path.join(srv, "whitelist.json"), "[]\n");
    sh("chown", ["-R", `${RUN_UID}:${RUN_UID}`, srv]);
    // pack served? (the same URL the client is told to download)
    if (s.resourcePack) {
      const f = await fetchSha1(s.resourcePack.url);
      if (!f.ok || f.sha1 !== s.resourcePack.sha1) throw new Error(`resource pack not served: ${f.ok ? `sha1 ${f.sha1} != ${s.resourcePack.sha1}` : f.error}`);
      ev.push(`pack_served: GET ${s.resourcePack.url} -> ${f.bytes} bytes, sha1 ${f.sha1} matches`);
    }
    const args = [
      `--unit=${unitOf(s.id)}`, `--slice=${SLICE}`, "--collect", "--quiet",
      `--property=RuntimeMaxSec=${ttl}`, `--property=MemoryMax=${CAPS.memMaxMb}M`, `--property=MemorySwapMax=0`, `--property=CPUQuota=${CAPS.cpuPct}%`, `--property=TasksMax=${CAPS.tasks}`,
      `--property=User=${RUN_UID}`, `--property=Group=${RUN_UID}`, "--property=NoNewPrivileges=yes", "--property=PrivateTmp=yes", "--property=ProtectSystem=strict", `--property=ReadWritePaths=${srv}`,
      "--property=ProtectHome=yes", `--property=WorkingDirectory=${srv}`, `--property=StandardOutput=append:${path.join(dir, "console.log")}`, `--property=StandardError=append:${path.join(dir, "console.log")}`,
      "--property=Nice=10", "--property=KillMode=control-group", "--property=TimeoutStopSec=30",
      java, `-Xmx${xmx}m`, "-Xms128m", "-XX:+UseSerialGC", "-XX:ActiveProcessorCount=2", "-XX:MaxMetaspaceSize=256m", "-XX:+ExitOnOutOfMemoryError",
      `-Djava.io.tmpdir=${srv}`, `-Duser.home=${srv}`, `-DbundlerRepoDir=${paperDir}`, `-Dnxeon.tryit=${s.id}`, "-jar", jar, "--nogui",
    ];
    const r = sh("systemd-run", args);
    if (r.status !== 0) throw new Error(`systemd-run failed: ${(r.stderr || r.stdout).slice(0, 300)}`);
    // auto teardown even if nobody calls stop: a transient timer runs `tryit.js stop <id>` after the TTL
    sh("systemd-run", [`--unit=${unitOf(s.id)}-reap`, "--quiet", "--collect", `--on-active=${ttl + 60}`, "--timer-property=AccuracySec=10s", process.execPath, __filename, "stop", s.id]);
    ev.push(`unit ${unitOf(s.id)}: RuntimeMaxSec=${ttl} MemoryMax=${CAPS.memMaxMb}M CPUQuota=${CAPS.cpuPct}% TasksMax=${CAPS.tasks} uid ${RUN_UID}; reap timer +${ttl + 60}s`);
    const t0 = Date.now();
    let done = false;
    while (Date.now() - t0 < 240000) {
      const log = fs.existsSync(path.join(dir, "console.log")) ? fs.readFileSync(path.join(dir, "console.log"), "utf8") : "";
      if (/\bDone \([0-9.]+s\)!/.test(log)) { done = true; break; }
      if (!isActive(s.id)) throw new Error(`server exited during boot: ${log.split("\n").slice(-4).join(" | ").slice(0, 400)}`);
      sh("sleep", ["1"]);
    }
    if (!done) throw new Error("server did not finish booting in 240 s");
    ev.push(`boot_done after ${Date.now() - t0} ms`);
    const c = await rcon(prep.rconPort, rconPassword);
    const checks = [];
    try {
      const wl = await c.cmd(`whitelist add ${s.owner.name}`);
      checks.push({ id: "whitelist", command: `whitelist add ${s.owner.name}`, reply: wl.trim().slice(0, 200), ok: /added|already/i.test(wl) });
      for (const k of s.rcon || []) {
        const reply = (await c.cmd(k.command)).trim();
        checks.push({ id: k.id || k.command, command: k.command, reply: reply.slice(0, 300), ok: (k.expect || []).every((e) => reply.includes(e)) });
      }
      const list = await c.cmd("whitelist list");
      checks.push({ id: "whitelist-only-owner", command: "whitelist list", reply: list.trim().slice(0, 200), ok: list.includes(s.owner.name) && /There (?:is|are) 1 whitelisted/i.test(list) });
    } finally { c.close(); }
    const ok = checks.every((x) => x.ok);
    const st = { ...prep, status: ok ? "ready" : "unhealthy" };
    fs.writeFileSync(path.join(dir, "state.json"), JSON.stringify(st), { mode: 0o600 });
    if (!ok) { const td = teardown(s.id, "a check failed"); out({ ok: false, code: "check_failed", error: "the Try-It server did not pass its checks; it was removed", checks, evidence: [...ev, ...td.evidence] }); process.exit(3); }
    out({ ok: true, session: publicView(st), checks, evidence: ev });
  } catch (e) {
    const td = teardown(s.id, "create failed");
    fail("create_failed", String(e.message || e).slice(0, 400), { evidence: [...ev, ...td.evidence] });
  }
}

function publicView(st) {
  const host = st.expose ? process.env.TRYIT_PUBLIC_HOST : "127.0.0.1";
  return { id: st.id, userId: st.userId, version: st.version, address: `${host}:${st.port}`, exposed: st.expose, owner: st.owner, createdAt: st.createdAt, expiresAt: st.expiresAt, status: isActive(st.id) ? st.status || "starting" : "stopped", resourcePack: st.resourcePack ? { url: st.resourcePack.url, sha1: st.resourcePack.sha1, required: st.resourcePack.required !== false } : null };
}

async function main() {
  const [cmd, arg] = process.argv.slice(2);
  if (cmd === "create") return create(arg);
  if (cmd === "status") { if (!ID_RE.test(arg || "")) fail("invalid", "bad id"); const st = readState(arg); return st ? out({ ok: true, session: publicView(st) }) : out({ ok: false, code: "not_found", error: "no such session" }); }
  if (cmd === "stop") { if (!ID_RE.test(arg || "")) fail("invalid", "bad id"); if (!readState(arg) && !isActive(arg)) return out({ ok: true, stopped: false, evidence: ["no such session (already removed)"] }); const r = withLock(() => teardown(arg, "stop requested")); return out({ ok: r.ok, stopped: true, evidence: r.evidence }); }
  if (cmd === "list") return out({ ok: true, sessions: sessions().map(publicView), caps: { ...CAPS, maxActive: MAX_ACTIVE, dailyPerUser: DAILY } });
  if (cmd === "reap") { const gone = sessions().filter((x) => !isActive(x.id) || Date.parse(x.expiresAt) < Date.now() - 60000); return out({ ok: true, reaped: gone.map((x) => ({ id: x.id, ...withLock(() => teardown(x.id, "expired")) })) }); }
  fail("invalid", "usage: tryit.js create <spec.json> | status <id> | stop <id> | list | reap");
}
main().catch((e) => fail("error", String(e.message || e).slice(0, 400)));

