// Cyrus r35 "TRY IT" (pure, client-safe): who may start a throwaway server to try a built mod, with which caps, and
// what the user is told to do to join (the connect flow). The node-2 controller (services/modbuilder/tools/tryit/
// tryit.js) enforces the same caps again and is the authority on "one active per user" / "max active" / "per day".
// OFF unless CYRUS_TRY_IT=1 (the API is a 404 then).
import { getVersion } from "../versions/registry";

export const TRYIT_FLAG = "CYRUS_TRY_IT";
export const tryItOn = (env: Record<string, string | undefined> = process.env) => env[TRYIT_FLAG] === "1";

/** OWNER: tune (the controller has the same hard ceilings). */
export const TRYIT_CAPS = { ttlMin: 20, maxTtlMin: 30, xmxMb: 1024, memMaxMb: 1536, cpuPct: 200, maxPlayers: 2, perUserActive: 1, dailyPerUser: 3 } as const;
/** Paid plans only (a throwaway server costs real node-2 capacity). Unknown / free = refused (fail closed). */
export const TRYIT_TIERS: readonly string[] = ["katara", "saka", "all"];

export type TryItBuild = { id: string; userId: string; status: string; mcVersion: string; jarPath: string | null; jarSha256: string | null; pluginName: string | null; pack: { url: string; sha1: string; required: boolean } | null };
export type TryItRefusal = { ok: false; status: number; code: string; error: string };

/** Every check the portal can make before it asks the build host (ownership, plan, build state, version, name). */
export function checkTryIt(i: { userId: string; tier: string | null; build: TryItBuild | null; mcName: unknown }): { ok: true; mcName: string } | TryItRefusal {
  const b = i.build;
  if (!b || b.userId !== i.userId) return { ok: false, status: 404, code: "not_found", error: "Build not found." };
  if (!i.tier || !TRYIT_TIERS.includes(i.tier)) return { ok: false, status: 403, code: "plan", error: "Try It is part of the paid Cyrus plans." };
  if (b.status !== "succeeded" || !b.jarPath || !b.jarSha256) return { ok: false, status: 409, code: "not_built", error: "This build has no finished plugin to try." };
  const v = getVersion(b.mcVersion);
  if (!v || !v.paperBuild || !v.paperServerSha256) return { ok: false, status: 409, code: "version", error: `Try It has no pinned Paper server for Minecraft ${b.mcVersion}.` };
  if (typeof i.mcName !== "string" || !/^[A-Za-z0-9_]{3,16}$/.test(i.mcName)) return { ok: false, status: 400, code: "mc_name", error: "Enter your Minecraft name (3-16 letters, digits or _): only that player can join." };
  if (b.pack && !/^https:\/\//.test(b.pack.url)) return { ok: false, status: 409, code: "pack", error: "This build's resource pack is not hosted yet, so players could not download it." };
  return { ok: true, mcName: i.mcName };
}

export type TryItSession = { id: string; version: string; address: string; exposed: boolean; owner: string; createdAt: string; expiresAt: string; status: string; resourcePack: { url: string; sha1: string; required: boolean } | null };

/** The connect flow, as the studio shows it. */
export function connectSteps(s: TryItSession, now = Date.now()): { title: string; steps: string[]; minutesLeft: number } {
  const minutesLeft = Math.max(0, Math.round((Date.parse(s.expiresAt) - now) / 60000));
  return {
    title: s.exposed ? "Your Try It server is ready" : "Your Try It server is running (build-host only, not reachable from the internet yet)",
    minutesLeft,
    steps: [
      `Open Minecraft Java ${s.version} (the exact version: other versions cannot join).`,
      `Multiplayer > Add Server > address ${s.address}.`,
      `Join as ${s.owner}: the server is whitelisted to that name only.`,
      ...(s.resourcePack ? [`Accept the server resource pack when asked${s.resourcePack.required ? " (required: the custom items look plain without it)" : ""}.`] : []),
      `It switches off by itself in about ${minutesLeft} minutes and everything on it is deleted. Nothing is installed on your own servers.`,
    ],
  };
}

