// Cyrus r35 "TRY IT" (server-only): talks to the node-2 controller (services/modbuilder/tools/tryit/tryit.js) through
// the same injectable Remote as Test Flight, and the framework-free HTTP layer behind app/api/cyrus/tryit.
// Order of checks: CYRUS_TRY_IT=1 (else 404) -> signed-in user (else 404) -> rate limit (429) -> input (400) -> the
// build is the caller's own (404) -> plan (403) -> build state / version (409) -> the controller's own caps (409:
// one per user, max active, per day). The controller never touches a customer server: it only runs on the build host.
import { createHash, randomBytes } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { getVersion } from "../versions/registry";
import { shq, sshRemote, type Remote } from "../testflight/client";
import { TF_DEFAULT_ROOT } from "../testflight/spec";
import { checkTryIt, connectSteps, TRYIT_CAPS, tryItOn, type TryItBuild, type TryItSession } from "./policy";

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const CONTROLLER = [["services/modbuilder/tools/tryit/tryit.js", "tryit.js"], ["services/modbuilder/tools/testflight/lib.js", "lib.js"]] as const;
const ID_RE = /^ti-[a-z0-9]{6,40}$/;

export type TryItDeps = {
  env: Record<string, string | undefined>;
  currentUser(): Promise<{ id: string } | null>;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec: number };
  build(userId: string, buildId: string): Promise<TryItBuild | null>;
  tierOf(userId: string): Promise<string | null>;
  remote?: Remote;
  root?: string;
  readFile?: (p: string) => Buffer;
  repoDir?: string;
};

export type ControllerReply = { ok: boolean; code?: string; error?: string; session?: TryItSession & { userId?: string }; sessions?: (TryItSession & { userId?: string })[]; checks?: unknown[]; evidence?: string[]; stopped?: boolean };

const parse = (stdout: string): ControllerReply => { try { return JSON.parse(stdout.trim().split("\n").filter(Boolean).pop() ?? ""); } catch { return { ok: false, code: "error", error: "the build host gave no answer" }; } };

/** Push the controller (+ the Test Flight lib it uses) when node-2's copy differs. */
export async function ensureController(remote: Remote, root: string, read: (p: string) => Buffer, repo: string) {
  const bin = `${root}/tryit-bin`;
  for (const [src, name] of CONTROLLER) {
    const data = read(path.join(repo, src));
    const have = await remote.exec(`sha256sum ${shq(`${bin}/${name}`)} 2>/dev/null | cut -d' ' -f1`);
    if (have.stdout.trim() === sha256(data)) continue;
    const r = await remote.exec(`mkdir -p ${shq(bin)} && cat > ${shq(`${bin}/.${name}.new`)} && mv -f ${shq(`${bin}/.${name}.new`)} ${shq(`${bin}/${name}`)}`, { input: data });
    if (r.code !== 0) throw new Error(`could not install the Try-It controller: ${r.stderr.slice(0, 200)}`);
  }
  return `${bin}/tryit.js`;
}

/** The controller spec for one session (registry pins; the mod jar is pushed to the build host first). */
export function tryItSpec(a: { id: string; userId: string; build: TryItBuild; jarRemotePath: string; mcName: string; ttlMin?: number; expose?: boolean; extraPlugins?: { path: string; sha256: string }[]; rcon?: { id?: string; command: string; expect?: string[] }[]; onlineMode?: boolean }) {
  const v = getVersion(a.build.mcVersion)!;
  return {
    schema: 1, id: a.id, userId: a.userId, version: v.id, javaRelease: v.javaRelease, paper: { build: v.paperBuild, sha256: v.paperServerSha256 },
    plugins: [{ path: a.jarRemotePath, sha256: a.build.jarSha256 }, ...(a.extraPlugins ?? [])],
    ...(a.build.pack ? { resourcePack: { url: a.build.pack.url, sha1: a.build.pack.sha1, required: a.build.pack.required } } : {}),
    owner: { name: a.mcName }, ttlSec: Math.min(TRYIT_CAPS.maxTtlMin, a.ttlMin ?? TRYIT_CAPS.ttlMin) * 60, xmxMb: TRYIT_CAPS.xmxMb, maxPlayers: 1,
    expose: a.expose === true, onlineMode: a.onlineMode ?? true, rcon: a.rcon ?? [{ id: "plugins", command: "plugins", expect: a.build.pluginName ? [a.build.pluginName] : [] }],
  };
}

export async function startTryIt(d: TryItDeps, a: { userId: string; build: TryItBuild; mcName: string; expose?: boolean; ttlMin?: number; extraPlugins?: { path: string; sha256: string }[]; rcon?: { id?: string; command: string; expect?: string[] }[]; onlineMode?: boolean; jarRemotePath?: string }): Promise<ControllerReply> {
  const remote = d.remote ?? sshRemote();
  const root = (d.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const read = d.readFile ?? ((p: string) => readFileSync(p));
  const bin = await ensureController(remote, root, read, d.repoDir ?? process.cwd());
  const id = `ti-${randomBytes(8).toString("hex")}`;
  const inbox = `${root}/inbox/tryit/${id}`;
  let jarRemote = a.jarRemotePath;
  try {
    if (!jarRemote) {
      const jar = read(a.build.jarPath!);
      if (sha256(jar) !== a.build.jarSha256) return { ok: false, code: "jar", error: "the build's jar does not match its recorded sha256" };
      jarRemote = `${inbox}/${a.build.pluginName?.replace(/[^A-Za-z0-9_-]/g, "") || "mod"}.jar`;
      const up = await remote.exec(`mkdir -p ${shq(inbox)} && cat > ${shq(jarRemote)}`, { input: jar });
      if (up.code !== 0) return { ok: false, code: "upload", error: `could not upload the plugin: ${up.stderr.slice(0, 200)}` };
    }
    const spec = tryItSpec({ id, userId: a.userId, build: a.build, jarRemotePath: jarRemote, mcName: a.mcName, ttlMin: a.ttlMin, expose: a.expose, extraPlugins: a.extraPlugins, rcon: a.rcon, onlineMode: a.onlineMode });
    const r = await remote.exec(`mkdir -p ${shq(inbox)} && cat > ${shq(`${inbox}/spec.json`)} && TF_ROOT=${shq(root)} node ${shq(bin)} create ${shq(`${inbox}/spec.json`)}`, { input: Buffer.from(JSON.stringify(spec)), timeoutMs: 360000 });
    return parse(r.stdout);
  } finally {
    await remote.exec(`rm -rf -- ${shq(inbox)}`);
  }
}

export async function controller(d: TryItDeps, cmd: "status" | "stop" | "list" | "reap", id?: string): Promise<ControllerReply> {
  if (id !== undefined && !ID_RE.test(id)) return { ok: false, code: "invalid", error: "bad session id" };
  const remote = d.remote ?? sshRemote();
  const root = (d.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const bin = await ensureController(remote, root, d.readFile ?? ((p: string) => readFileSync(p)), d.repoDir ?? process.cwd());
  const r = await remote.exec(`TF_ROOT=${shq(root)} node ${shq(bin)} ${cmd}${id ? ` ${shq(id)}` : ""}`, { timeoutMs: 120000 });
  return parse(r.stdout);
}

// ------------------------------------------------------------------------------------------------ HTTP layer
const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const NOT_FOUND = () => json(404, { error: "Not found" });
const CODE_STATUS: Record<string, number> = { user_active: 409, busy: 409, daily_limit: 429, invalid: 400, not_found: 404 };

async function gate(d: TryItDeps, max: number): Promise<{ ok: true; uid: string } | { ok: false; res: Response }> {
  if (!tryItOn(d.env)) return { ok: false, res: NOT_FOUND() };
  const u = await d.currentUser().catch(() => null);
  if (!u) return { ok: false, res: NOT_FOUND() };
  const rl = d.rateLimit(`cyrus:tryit:${u.id}`, max, 60_000);
  if (!rl.ok) return { ok: false, res: json(429, { error: `Too many requests. Retry in ${rl.retryAfterSec}s.`, code: "rate_limited" }) };
  return { ok: true, uid: u.id };
}

const view = (s: TryItSession) => ({ session: { ...s, userId: undefined }, connect: connectSteps(s) });

/** POST { buildId, mcName } -> start one session for the caller's own build. */
export async function handleTryItStart(req: Request, d: TryItDeps): Promise<Response> {
  const g = await gate(d, 4);
  if (!g.ok) return g.res;
  const body = (await req.json().catch(() => null)) as { buildId?: unknown; mcName?: unknown } | null;
  if (!body || typeof body.buildId !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(body.buildId)) return json(400, { error: "buildId is required", code: "invalid" });
  const build = await d.build(g.uid, body.buildId);
  const tier = await d.tierOf(g.uid).catch(() => null);
  const c = checkTryIt({ userId: g.uid, tier, build, mcName: body.mcName });
  if (!c.ok) return json(c.status, { error: c.error, code: c.code });
  const r = await startTryIt(d, { userId: g.uid, build: build!, mcName: c.mcName, expose: d.env.CYRUS_TRY_IT_EXPOSE === "1" }).catch((e) => ({ ok: false, code: "error", error: String((e as Error).message).slice(0, 200) }) as ControllerReply);
  if (!r.ok || !r.session) return json(CODE_STATUS[r.code ?? ""] ?? 502, { error: r.error ?? "Try It could not start", code: r.code ?? "error" });
  return json(201, view(r.session));
}

/** GET ?id= -> the caller's session (or their active one when no id). */
export async function handleTryItStatus(url: URL, d: TryItDeps): Promise<Response> {
  const g = await gate(d, 60);
  if (!g.ok) return g.res;
  const id = url.searchParams.get("id");
  const r = await controller(d, id ? "status" : "list", id ?? undefined);
  const mine = (r.session ? [r.session] : r.sessions ?? []).filter((s) => s.userId === g.uid);
  if (!mine.length) return id ? NOT_FOUND() : json(200, { session: null });
  return json(200, view(mine[0]));
}

/** DELETE ?id= -> stop + delete the caller's own session now. */
export async function handleTryItStop(url: URL, d: TryItDeps): Promise<Response> {
  const g = await gate(d, 10);
  if (!g.ok) return g.res;
  const id = url.searchParams.get("id") ?? "";
  const st = await controller(d, "status", id);
  if (!st.session || st.session.userId !== g.uid) return NOT_FOUND();
  const r = await controller(d, "stop", id);
  return json(r.ok ? 200 : 502, { stopped: !!r.stopped && r.ok, evidence: r.evidence ?? [] });
}

