"use client";
// Cyrus r35 Try It: the minimal UI hook. Drop next to a finished build (behind CYRUS_TRY_IT; the API 404s while off,
// and this renders nothing then). Name -> start -> the connect steps -> stop. Not placed on any page yet.
import { useEffect, useState } from "react";

type Connect = { title: string; steps: string[]; minutesLeft: number };
type View = { session: { id: string; address: string; expiresAt: string; status: string } | null; connect?: Connect };

export function TryItButton({ buildId }: { buildId: string }) {
  const [name, setName] = useState("");
  const [view, setView] = useState<View | null>(null);
  const [off, setOff] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    fetch("/api/cyrus/tryit").then(async (r) => { if (r.status === 404) setOff(true); else if (r.ok) setView(await r.json()); }).catch(() => setOff(true));
  }, []);
  if (off) return null;

  const start = async () => {
    setBusy(true); setErr(null);
    const r = await fetch("/api/cyrus/tryit", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ buildId, mcName: name }) });
    const j = await r.json().catch(() => ({}));
    if (r.ok) setView(j); else setErr(j.error ?? "Try It could not start.");
    setBusy(false);
  };
  const stop = async () => {
    if (!view?.session) return;
    setBusy(true);
    await fetch(`/api/cyrus/tryit?id=${encodeURIComponent(view.session.id)}`, { method: "DELETE" });
    setView({ session: null }); setBusy(false);
  };

  if (view?.session && view.connect) {
    return (
      <div className="cy-tryit" role="status">
        <strong>{view.connect.title}</strong>
        <ol>{view.connect.steps.map((s) => <li key={s}>{s}</li>)}</ol>
        <button type="button" onClick={stop} disabled={busy}>Stop and delete it now</button>
      </div>
    );
  }
  return (
    <div className="cy-tryit">
      <label>Your Minecraft name <input value={name} onChange={(e) => setName(e.target.value)} maxLength={16} placeholder="Steve" /></label>
      <button type="button" onClick={start} disabled={busy || name.length < 3}>{busy ? "Starting (about a minute)..." : "Try it on a temporary server"}</button>
      {err ? <p role="alert">{err}</p> : null}
    </div>
  );
}

