// REAL Try It flight on node-2 (not part of the unit suite): create -> pack served -> RCON check -> teardown, with the
// caps exercised (a second session for the same user is refused). Runs ON node-2 through devhost (local transport):
//   devhost run --lock -- npx tsx test/cyrus-tryit-real.ts --local [--out f.json]
// The session is NOT exposed (127.0.0.1, offline mode): exposing needs the owner's firewall range + DNS + online mode.
// The pack is served by a throwaway HTTP server in this process on 127.0.0.1 (in production: the hosted pack URL).
import { createHash } from "node:crypto";
import { createServer } from "node:http";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { buildPack } from "../lib/cyrus/textures/pack";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { HEALTH_POTION } from "../lib/cyrus/textures/sample-items";
import { TF_DEFAULT_ROOT } from "../lib/cyrus/testflight/spec";
import { controller, startTryIt, type TryItDeps } from "../lib/cyrus/tryit/service";
import { connectSteps } from "../lib/cyrus/tryit/policy";
import { localRemote } from "./cyrus-legacy-real";

const NS = "nx_r35tryit";
const FX = `${TF_DEFAULT_ROOT}/inbox/fx/TfItemModel-1.0.0.jar`;

async function main() {
  const outIdx = process.argv.indexOf("--out");
  const ruby = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
  const specs = [ruby, HEALTH_POTION].map((s) => { const c = checkSpec(s); if (!c.ok) throw new Error(c.error); return c.spec; });
  const b = buildPack({ namespace: NS, description: "TryIt: custom textures by Cyrus", mcVersion: "1.21.11", textures: specs });
  if (!b.ok) throw new Error(b.error);
  let hits = 0;
  const http = createServer((req, res) => {
    if (req.url === `/p/${b.pack.sha1}.zip`) { hits++; res.writeHead(200, { "content-type": "application/zip", "content-length": b.pack.zip.length }); res.end(b.pack.zip); }
    else { res.writeHead(404); res.end(); }
  });
  await new Promise<void>((r) => http.listen(0, "127.0.0.1", () => r()));
  const port = (http.address() as { port: number }).port;
  const jar = readFileSync(FX);
  const deps: TryItDeps = { env: {}, currentUser: async () => null, rateLimit: () => ({ ok: true, retryAfterSec: 0 }), build: async () => null, tierOf: async () => "all", remote: process.argv.includes("--local") ? localRemote : undefined, repoDir: process.cwd() };
  const build = { id: "mbtryit", userId: "u-tryit-flight", status: "succeeded", mcVersion: "1.21.11", jarPath: FX, jarSha256: createHash("sha256").update(jar).digest("hex"), pluginName: "TfItemModel", pack: { url: `http://127.0.0.1:${port}/p/${b.pack.sha1}.zip`, sha1: b.pack.sha1, required: true } };
  const out: Record<string, unknown> = { pack: { sha1: b.pack.sha1, bytes: b.pack.bytes, format: b.pack.packFormat } };
  try {
    const t0 = Date.now();
    const r = await startTryIt(deps, {
      userId: build.userId, build, mcName: "TryItOwner", ttlMin: 5, onlineMode: false, expose: false, jarRemotePath: FX,
      rcon: [{ id: "item-look", command: `tfitem ${NS} ruby_sword`, expect: [`itemModel=${NS}:ruby_sword`, "material=IRON_SWORD"] }, { id: "plugins", command: "plugins", expect: ["TfItemModel"] }],
    });
    out.create = { ...r, ms: Date.now() - t0 };
    console.log(`create: ${r.ok ? "ok" : `FAILED ${r.code}: ${r.error}`}`);
    if (r.ok && r.session) {
      out.connect = connectSteps(r.session);
      out.packHitsAfterCreate = hits;
      const unit = await localRemote.exec(`systemctl show -p ActiveState,MemoryMax,CPUQuotaPerSecUSec,TasksMax,RuntimeMaxUSec,User cyrus-tryit-${r.session.id}.service; systemctl list-timers --all --no-legend 'cyrus-tryit-${r.session.id}-reap.timer' | wc -l`);
      out.unit = unit.stdout.trim().split("\n");
      // cap: a second session for the same user is refused before anything boots
      const again = await startTryIt(deps, { userId: build.userId, build, mcName: "TryItOwner", ttlMin: 5, onlineMode: false, jarRemotePath: FX });
      out.secondForSameUser = { ok: again.ok, code: again.code, error: again.error };
      console.log(`second session same user: ${again.ok ? "STARTED (cap broken)" : `refused (${again.code})`}`);
      out.status = await controller(deps, "status", r.session.id);
      const stop = await controller(deps, "stop", r.session.id);
      out.stop = stop;
      console.log(`stop: ${stop.ok ? "ok" : "FAILED"} ${(stop.evidence ?? []).join(" / ")}`);
      const after = await localRemote.exec(`systemctl is-active cyrus-tryit-${r.session.id}.service; ls ${TF_DEFAULT_ROOT}/tryit/ | grep -c '^ti-' ; ss -ltn | grep -c ':47[2][0-9][0-9] '`);
      out.afterTeardown = after.stdout.trim().split("\n");
      out.listAfter = await controller(deps, "list");
    }
  } finally { http.close(); }
  if (outIdx > 0) writeFileSync(process.argv[outIdx + 1], JSON.stringify(out, null, 1));
  else console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

