// Cyrus r35 Try It (no server boots here): policy (ownership, plan, build state, version, name, hosted pack), the
// connect flow, the controller's spec validation (spawned with a bad spec, refused before anything starts), and the
// HTTP layer with a fake build host (flag off = 404, ownership on every route, the controller's caps passed through).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { checkTryIt, connectSteps, tryItOn, type TryItBuild } from "../lib/cyrus/tryit/policy";
import { handleTryItStart, handleTryItStatus, handleTryItStop, tryItSpec, type TryItDeps } from "../lib/cyrus/tryit/service";
import type { Remote } from "../lib/cyrus/testflight/client";

const B: TryItBuild = { id: "b1", userId: "u1", status: "succeeded", mcVersion: "1.21.11", jarPath: "/x/mod.jar", jarSha256: "a".repeat(64), pluginName: "Ruby", pack: { url: "https://packs.example/p/x.zip", sha1: "b".repeat(40), required: true } };

describe("policy", () => {
  it("flag off by default", () => { assert.equal(tryItOn({}), false); assert.equal(tryItOn({ CYRUS_TRY_IT: "1" }), true); });
  it("ownership, plan, build, version, name, pack", () => {
    const c = (o: Partial<Parameters<typeof checkTryIt>[0]> = {}) => checkTryIt({ userId: "u1", tier: "all", build: B, mcName: "Steve", ...o });
    assert.deepEqual(c(), { ok: true, mcName: "Steve" });
    assert.equal((c({ userId: "u2" }) as { code: string }).code, "not_found");
    assert.equal((c({ tier: "free" }) as { code: string }).code, "plan");
    assert.equal((c({ tier: null }) as { code: string }).code, "plan");
    assert.equal((c({ build: { ...B, status: "failed" } }) as { code: string }).code, "not_built");
    assert.equal((c({ build: { ...B, mcVersion: "26.3" } }) as { code: string }).code, "version");
    assert.equal((c({ mcName: "a b" }) as { code: string }).code, "mc_name");
    assert.equal((c({ build: { ...B, pack: { ...B.pack!, url: "http://x" } } }) as { code: string }).code, "pack");
  });
  it("connect steps say version, address, whitelist, pack, expiry", () => {
    const s = connectSteps({ id: "ti-abcdef", version: "1.21.11", address: "try.example:47210", exposed: true, owner: "Steve", createdAt: "", expiresAt: new Date(Date.now() + 20 * 60000).toISOString(), status: "ready", resourcePack: B.pack });
    assert.equal(s.minutesLeft, 20);
    assert.match(s.steps.join(" "), /Java 1\.21\.11.*try\.example:47210.*Steve.*resource pack.*20 minutes/);
  });
  it("spec: registry pins, ttl capped, online mode default", () => {
    const sp = tryItSpec({ id: "ti-abcdef12", userId: "u1", build: B, jarRemotePath: "/r/m.jar", mcName: "Steve", ttlMin: 999 });
    assert.equal(sp.ttlSec, 30 * 60);
    assert.equal(sp.paper.build, 132);
    assert.equal(sp.onlineMode, true);
    assert.equal(sp.expose, false);
  });
});

describe("controller validation (refused before anything starts)", () => {
  const run = (spec: unknown) => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), "tryit-")), f = path.join(root, "s.json");
    fs.writeFileSync(f, JSON.stringify(spec));
    const r = spawnSync(process.execPath, [path.join(__dirname, "../services/modbuilder/tools/tryit/tryit.js"), "create", f], { encoding: "utf8", env: { PATH: process.env.PATH, TF_ROOT: root } });
    fs.rmSync(root, { recursive: true, force: true });
    return JSON.parse(r.stdout.trim());
  };
  const good = { schema: 1, id: "ti-abcdef12", userId: "u1", version: "1.21.11", javaRelease: 21, paper: { sha256: "c".repeat(64) }, plugins: [{ path: "/tmp/x.jar", sha256: "d".repeat(64) }], owner: { name: "Steve" } };
  it("offline-mode on a public port, forbidden rcon, foreign paths", () => {
    const r = run({ ...good, expose: true, onlineMode: false, rcon: [{ command: "op Steve" }] });
    assert.equal(r.ok, false);
    assert.equal(r.code, "invalid");
    assert.match(r.error, /exposed session must be online-mode/);
    assert.match(r.error, /rcon command not allowed: op Steve/);
    assert.match(r.error, /bad plugin \/tmp\/x\.jar/);
  });
});

describe("HTTP layer", () => {
  const calls: string[] = [];
  const fakeRemote = (sessions: Record<string, unknown>[]): Remote => ({
    exec: async (command) => {
      calls.push(command);
      if (command.startsWith("sha256sum")) return { code: 0, stdout: "", stderr: "" };
      if (/ create /.test(command)) return { code: 0, stdout: JSON.stringify({ ok: true, session: { id: "ti-0123456789abcdef", userId: "u1", version: "1.21.11", address: "127.0.0.1:47210", exposed: false, owner: "Steve", createdAt: "", expiresAt: new Date(Date.now() + 60000).toISOString(), status: "ready", resourcePack: null } }) + "\n", stderr: "" };
      if (/ status /.test(command)) { const id = command.split(" ").pop()!.replace(/'/g, ""); const s = sessions.find((x) => x.id === id); return { code: 0, stdout: JSON.stringify(s ? { ok: true, session: s } : { ok: false, code: "not_found" }), stderr: "" }; }
      if (/ stop /.test(command)) return { code: 0, stdout: JSON.stringify({ ok: true, stopped: true, evidence: ["gone"] }), stderr: "" };
      if (/ list$/.test(command)) return { code: 0, stdout: JSON.stringify({ ok: true, sessions }), stderr: "" };
      return { code: 0, stdout: "", stderr: "" };
    },
  });
  const deps = (o: Partial<TryItDeps> = {}): TryItDeps => ({
    env: { CYRUS_TRY_IT: "1" }, currentUser: async () => ({ id: "u1" }), rateLimit: () => ({ ok: true, retryAfterSec: 0 }),
    build: async (u, id) => (u === B.userId && id === B.id ? B : null), tierOf: async () => "all",
    remote: fakeRemote([{ id: "ti-0123456789abcdef", userId: "u1", version: "1.21.11", address: "a:1", exposed: false, owner: "Steve", createdAt: "", expiresAt: "", status: "ready", resourcePack: null }, { id: "ti-ffffffffffffffff", userId: "u2", version: "1.21.11", address: "a:2", exposed: false, owner: "X", createdAt: "", expiresAt: "", status: "ready", resourcePack: null }]),
    readFile: (p) => (p.endsWith("mod.jar") ? Buffer.from("jar") : Buffer.from("// file")), repoDir: "/repo", ...o,
  });
  const post = (body: unknown) => new Request("http://x/api/cyrus/tryit", { method: "POST", body: JSON.stringify(body) });
  it("404 while off or signed out", async () => {
    assert.equal((await handleTryItStart(post({ buildId: "b1", mcName: "Steve" }), deps({ env: {} }))).status, 404);
    assert.equal((await handleTryItStart(post({ buildId: "b1", mcName: "Steve" }), deps({ currentUser: async () => null }))).status, 404);
  });
  it("start: checks before the build host; jar hash verified", async () => {
    assert.equal((await handleTryItStart(post({}), deps())).status, 400);
    assert.equal((await handleTryItStart(post({ buildId: "nope", mcName: "Steve" }), deps())).status, 404);
    assert.equal((await handleTryItStart(post({ buildId: "b1", mcName: "Steve" }), deps({ tierOf: async () => "free" }))).status, 403);
    const badJar = await handleTryItStart(post({ buildId: "b1", mcName: "Steve" }), deps());
    assert.equal(badJar.status, 502, "jar sha256 mismatch is refused");
    const sha = (await import("node:crypto")).createHash("sha256").update("jar").digest("hex");
    const ok = await handleTryItStart(post({ buildId: "b1", mcName: "Steve" }), deps({ build: async () => ({ ...B, jarSha256: sha }) }));
    assert.equal(ok.status, 201);
    const j = await ok.json();
    assert.equal(j.session.userId, undefined);
    assert.match(j.connect.steps[1], /127\.0\.0\.1:47210/);
  });
  it("status/stop only for the caller's own session", async () => {
    const mine = await handleTryItStatus(new URL("http://x/?id=ti-0123456789abcdef"), deps());
    assert.equal(mine.status, 200);
    assert.equal((await handleTryItStatus(new URL("http://x/?id=ti-ffffffffffffffff"), deps())).status, 404);
    assert.equal((await handleTryItStop(new URL("http://x/?id=ti-ffffffffffffffff"), deps())).status, 404);
    const st = await handleTryItStop(new URL("http://x/?id=ti-0123456789abcdef"), deps());
    assert.equal(st.status, 200);
    assert.equal((await st.json()).stopped, true);
    assert.ok(!calls.some((c) => /ssh|qm |pct /.test(c)), "only the build host controller is called");
  });
});

